#!/usr/bin/env bash
#
# Cross-platform application installer / launcher controller
#
# Source directory contents:
#   Installer.sh     (name/capitalization may vary)
#   icon.png        (optional; a default icon is auto-generated on first run if absent)
#   Start.sh        (created automatically if missing)
#
# The DIRECTORY THIS SCRIPT IS RUN FROM is the installation directory.
#
# Supported launcher targets:
#   Linux   : freedesktop .desktop launcher
#   macOS   : /Applications/<App>.app  (10.13+)
#   Windows : all-users Start Menu .lnk (8.1/10/11)
#
# Windows note:
#   This installer requires a Bash environment such as Git for Windows.
#
# Installation identity:
#   The full installer filename stem identifies the application install.
#   Renaming this file creates a separate installation with independent
#   launch state and launcher registration. On Windows, each identity also
#   gets its own Add or Remove Programs entry. Rename the file back to an
#   earlier name to update or uninstall that earlier identity.
#
# First install for a name:
#   Prompts for the full script/executable path and generates that
#   installation's editable Start.sh with cat.
#
# First run:
#   installs a dedicated persistent Installer manager application only.
# Subsequent Installer-app runs:
#   install/remove managed applications while preserving the manager.
# Named child install / stale launcher:
#   create or update the platform launcher, then exit.
#
# Subsequent run with a current launcher:
#   launch Start.sh with administrative/root privileges.
#
# Uninstall:
#   ./Installer.sh -u
#   Removes the platform launcher, generated platform icon/support files,
#   launcher state, Start.sh, and icon.png.
#   The installer itself and other application files are preserved.
#
# Linux category behavior:
#   Filename suffix selects category (e.g. -Utility, -System, -Other).
#   -Other omits Categories= so the desktop can use its catch-all group.
#
# Platform icon behavior:
#   Linux   : icon.png
#   macOS   : icon.png -> icon.icns inside the generated .app bundle
#   Windows : icon.png -> icon.ico inside .launcher
#

set -u

if [ -n "${RZ27_INSTALL_DIR:-}" ]; then
    INSTALL_DIR="$RZ27_INSTALL_DIR"
else
    INSTALL_DIR="$(pwd -P)"
fi

# Preserve the actual capitalization/name used for this installer.
# Linux filesystems are normally case-sensitive, so assuming "installer.sh"
# breaks launchers when the file is named "Installer.sh", "INSTALLER.sh", etc.
INSTALLER_BASENAME="$(basename -- "${BASH_SOURCE[0]}")"

# Windows Add/Remove Programs uses a copied uninstaller. The copy sets
# RZ27_INSTALLER_IDENTITY so it can address the original name-based install.
if [ -n "${RZ27_INSTALLER_IDENTITY:-}" ]; then
    INSTALLER_BASENAME="$RZ27_INSTALLER_IDENTITY"
fi

INSTALLER_FILE="$INSTALL_DIR/$(basename -- "${BASH_SOURCE[0]}")"

# icon.png is shared source artwork for installs in this directory.
# Start.sh is assigned after the installer-name-derived application ID is known,
# so renaming the installer creates an independent launch configuration.
ICON_FILE="$INSTALL_DIR/icon.png"

# ------------------------------------------------------------
# Application name + category from installer filename
#
# Examples:
#   Installer-Utility.sh      -> Name: Installer, Category: Utility
#   AutoKernel-System.sh      -> Name: AutoKernel, Category: System
#   RZ-27-Other.sh            -> Name: RZ-27, no Categories= line
#
# "-Other" is an installer hint for the desktop's catch-all group.
# It is intentionally NOT written as Categories=Other because "Other"
# is not a freedesktop application category.
# ------------------------------------------------------------

INSTALLER_STEM="${INSTALLER_BASENAME%.*}"
APP_NAME="$INSTALLER_STEM"
APP_CATEGORY=""

case "$INSTALLER_STEM" in
    *-Utility)
        APP_NAME="${INSTALLER_STEM%-Utility}"
        APP_CATEGORY="Utility"
        ;;
    *-System)
        APP_NAME="${INSTALLER_STEM%-System}"
        APP_CATEGORY="System"
        ;;
    *-Development)
        APP_NAME="${INSTALLER_STEM%-Development}"
        APP_CATEGORY="Development"
        ;;
    *-Graphics)
        APP_NAME="${INSTALLER_STEM%-Graphics}"
        APP_CATEGORY="Graphics"
        ;;
    *-AudioVideo)
        APP_NAME="${INSTALLER_STEM%-AudioVideo}"
        APP_CATEGORY="AudioVideo"
        ;;
    *-Network)
        APP_NAME="${INSTALLER_STEM%-Network}"
        APP_CATEGORY="Network"
        ;;
    *-Office)
        APP_NAME="${INSTALLER_STEM%-Office}"
        APP_CATEGORY="Office"
        ;;
    *-Game)
        APP_NAME="${INSTALLER_STEM%-Game}"
        APP_CATEGORY="Game"
        ;;
    *-Education)
        APP_NAME="${INSTALLER_STEM%-Education}"
        APP_CATEGORY="Education"
        ;;
    *-Settings)
        APP_NAME="${INSTALLER_STEM%-Settings}"
        APP_CATEGORY="Settings"
        ;;
    *-Other)
        APP_NAME="${INSTALLER_STEM%-Other}"
        APP_CATEGORY=""
        ;;
esac

[ -n "$APP_NAME" ] || APP_NAME="$INSTALLER_STEM"

# The persistent Installer manager may supply a custom visible application
# name and icon source for a child installation. The installer filename still
# remains the stable install identity used for uninstall/state lookup.
if [ -n "${RZ27_CUSTOM_APP_NAME:-}" ]; then
    APP_NAME="$RZ27_CUSTOM_APP_NAME"
fi

if [ -n "${RZ27_CUSTOM_ICON_FILE:-}" ]; then
    ICON_FILE="$RZ27_CUSTOM_ICON_FILE"
fi

APP_ID="$(
    printf '%s' "$INSTALLER_STEM" |
        tr '[:upper:]' '[:lower:]' |
        sed 's/[^a-z0-9._-]/-/g'
)"
[ -n "$APP_ID" ] || APP_ID="custom-app"

# Namespace the desktop-file ID as recommended by the freedesktop menu
# specification. This does not change the visible application Name.
DESKTOP_APP_ID="rz27-$APP_ID"

# Previous versions derived the ID from the installation-directory name.
# Retain that ID only so stale per-user launchers can be cleaned up; a
# per-user entry can otherwise override the new system-wide entry.
LEGACY_APP_NAME="$(basename "$INSTALL_DIR")"
LEGACY_APP_ID="$(
    printf '%s' "$LEGACY_APP_NAME" |
        tr '[:upper:]' '[:lower:]' |
        sed 's/[^a-z0-9._-]/-/g'
)"

# ------------------------------------------------------------
# Installation state
#
# This records the exact content checksum of Start.sh and
# icon.png from the last successful launcher installation.
#
# If neither file has changed and the platform launcher still
# matches its expected parameters, no launcher/icon/cache work
# is performed; execution goes directly to Start.sh.
# ------------------------------------------------------------

# Each installer filename is a separate installation identity.
# Renaming Installer-Other.sh changes DESKTOP_APP_ID and therefore creates
# independent state and an independent Start.sh without modifying the old one.
LAUNCHER_ROOT="$INSTALL_DIR/.launcher"
STATE_DIR="$LAUNCHER_ROOT/$DESKTOP_APP_ID"
STATE_FILE="$STATE_DIR/install.state"
START_FILE="$STATE_DIR/Start.sh"
INSTALL_METADATA_FILE="$STATE_DIR/install-metadata.conf"
ICON_BOOTSTRAP_MARKER="$STATE_DIR/default-icon-bootstrap.done"

# Persistent installer-manager identity. This app exists independently of
# child installations and is removed only when no managed installs remain.
MANAGER_ID="rz27-installer-manager"
MANAGER_NAME="Installer"
MANAGER_STATE_DIR="$LAUNCHER_ROOT/__installer_manager"
MANAGER_STATE_FILE="$MANAGER_STATE_DIR/install.state"
MANAGER_ICON_MARKER="$MANAGER_STATE_DIR/icon.ready"

# Transparent, human-readable registry of scripts installed by the manager.
rz27_registry_paths()
{
    case "$PLATFORM" in
        windows)
            windows_find_powershell
            APPDATA_NATIVE="$("$POWERSHELL_EXE" -NoProfile -Command \
                "[Environment]::GetFolderPath('ApplicationData')" 2>/dev/null |
                tr -d '\r')"
            [ -n "$APPDATA_NATIVE" ] || die "Could not determine Windows AppData directory."
            if command -v cygpath >/dev/null 2>&1; then
                RZ27_RECORD_DIR="$(cygpath -u "$APPDATA_NATIVE")/RZ-27"
            else
                RZ27_RECORD_DIR="$APPDATA_NATIVE/RZ-27"
            fi
            ;;
        macos)
            RZ27_RECORD_DIR="$HOME/Library/Application Support/RZ-27"
            ;;
        linux)
            RZ27_RECORD_DIR="${XDG_STATE_HOME:-$HOME/.local/state}/RZ-27"
            ;;
        *)
            RZ27_RECORD_DIR="$HOME/.rz27"
            ;;
    esac
    RZ27_INSTALL_LOG="$RZ27_RECORD_DIR/List-Of-Installed-Scripts.log"
}

rz27_ensure_registry()
{
    rz27_registry_paths
    mkdir -p "$RZ27_RECORD_DIR" || die "Could not create RZ-27 records directory."
    [ -f "$RZ27_INSTALL_LOG" ] || : > "$RZ27_INSTALL_LOG"
}

rz27_log_escape()
{
    printf '%s' "$1" | sed 's/|/%7C/g'
}

rz27_start_target_for_log()
{
    if [ ! -f "$START_FILE" ]; then
        printf '%s' "$START_FILE"
        return 0
    fi
    TARGET_LINE="$(sed -n 's/^SCRIPT_TO_RUN=//p' "$START_FILE" | head -n 1)"
    [ -n "$TARGET_LINE" ] && printf '%s' "$TARGET_LINE" || printf '%s' "$START_FILE"
}

rz27_launch_command_for_log()
{
    if [ -f "$INSTALL_METADATA_FILE" ]; then
        VALUE="$(sed -n 's/^LAUNCH_COMMAND=//p' "$INSTALL_METADATA_FILE" | head -n 1)"
        printf '%s' "$VALUE"
        return 0
    fi

    printf '%s' "${RZ27_CUSTOM_LAUNCH_COMMAND:-}"
}

rz27_registry_add_current()
{
    if [ "$APP_NAME" = "$MANAGER_NAME" ] && [ -z "${RZ27_MANAGER_CHILD:-}" ]; then
        return 0
    fi
    rz27_ensure_registry

    RID="$(rz27_log_escape "$DESKTOP_APP_ID")"
    RNAME="$(rz27_log_escape "$INSTALLER_STEM")"
    RAPP="$(rz27_log_escape "$APP_NAME")"
    RCATEGORY="$(rz27_log_escape "${APP_CATEGORY:-Other}")"
    RTARGET="$(rz27_log_escape "$(rz27_start_target_for_log)")"
    RCOMMAND="$(rz27_log_escape "$(rz27_launch_command_for_log)")"
    RICON="$(rz27_log_escape "$ICON_FILE")"
    RSOURCE="$(rz27_log_escape "${RZ27_SOURCE_SCRIPT:-}")"
    RWORKDIR="$(rz27_log_escape "${RZ27_CUSTOM_WORKDIR:-}")"
    RDIR="$(rz27_log_escape "$INSTALL_DIR")"
    RPLATFORM="$(rz27_log_escape "$PLATFORM")"

    TMP_LOG="$(mktemp)" || die "Could not update RZ-27 install registry."
    awk -F'|' -v id="$RID" '$1 != id { print }' "$RZ27_INSTALL_LOG" > "$TMP_LOG" 2>/dev/null || true
    printf '%s|%s|%s|%s|%s|%s|%s|%s|%s|%s|%s\n'         "$RID" "$RNAME" "$RAPP" "$RCATEGORY" "$RTARGET" "$RCOMMAND" "$RICON"         "$RSOURCE" "$RWORKDIR" "$RDIR" "$RPLATFORM" >> "$TMP_LOG"
    mv "$TMP_LOG" "$RZ27_INSTALL_LOG" || die "Could not write RZ-27 install registry."
}

rz27_registry_remove_current()
{
    if [ "$APP_NAME" = "$MANAGER_NAME" ] && [ -z "${RZ27_MANAGER_CHILD:-}" ]; then
        return 0
    fi
    rz27_ensure_registry

    RID="$(rz27_log_escape "$DESKTOP_APP_ID")"
    TMP_LOG="$(mktemp)" || die "Could not update RZ-27 install registry."
    awk -F'|' -v id="$RID" '$1 != id { print }' "$RZ27_INSTALL_LOG" > "$TMP_LOG" 2>/dev/null || true
    mv "$TMP_LOG" "$RZ27_INSTALL_LOG" || die "Could not write RZ-27 install registry."
}

rz27_registry_show()
{
    rz27_ensure_registry
    printf '\nRZ-27 transparent install registry:\n  %s\n\n' "$RZ27_INSTALL_LOG"

    if [ ! -s "$RZ27_INSTALL_LOG" ]; then
        printf 'No managed scripts are currently recorded.\n'
        return 0
    fi

    awk -F'|' '
        {
            for (i = 2; i <= 11; i++) gsub(/%7C/, "|", $i)
            printf "  - %s\n", $2
            printf "      App name : %s\n", $3
            printf "      Category : %s\n", $4
            printf "      Target   : %s\n", $5
            if ($6 != "") {
                printf "      Command  : %s\n", $6
            } else {
                printf "      Command  : direct execution\n"
            }
            printf "      Icon     : %s\n", $7
            if ($8 != "") printf "      Source   : %s\n", $8
            if ($9 != "") printf "      Run dir  : %s\n", $9
            printf "      Install  : %s\n", $10
            printf "      Platform : %s\n", $11
        }
    ' "$RZ27_INSTALL_LOG"
}

rz27_registry_cleanup_if_empty()
{
    rz27_registry_paths
    if [ -f "$RZ27_INSTALL_LOG" ] && [ ! -s "$RZ27_INSTALL_LOG" ]; then
        rm -f "$RZ27_INSTALL_LOG" 2>/dev/null || true
        rmdir "$RZ27_RECORD_DIR" 2>/dev/null || true
    fi
}

file_fingerprint()
{
    FILE_TO_HASH="$1"

    [ -f "$FILE_TO_HASH" ] || {
        printf 'missing'
        return
    }

    # cksum is available on the targeted Unix systems and in
    # common Windows Bash environments such as Git Bash.
    cksum "$FILE_TO_HASH" 2>/dev/null | awk '{print $1 ":" $2}'
}

current_start_fingerprint()
{
    file_fingerprint "$START_FILE"
}

current_icon_fingerprint()
{
    file_fingerprint "$ICON_FILE"
}

derived_icon_fingerprint()
{
    case "${PLATFORM:-unknown}" in
        linux)
            linux_desktop_file
            file_fingerprint "$LINUX_SYSTEM_ICON"
            ;;
        macos)
            mac_paths
            file_fingerprint "$MAC_ICON"
            ;;
        windows)
            windows_paths
            file_fingerprint "$WIN_ICON"
            ;;
        *)
            printf 'none'
            ;;
    esac
}

state_is_current()
{
    [ -f "$STATE_FILE" ] || return 1

    EXPECTED_START="$(current_start_fingerprint)"
    EXPECTED_ICON="$(current_icon_fingerprint)"
    EXPECTED_DERIVED="$(derived_icon_fingerprint)"

    STORED_START="$(sed -n 's/^START=//p' "$STATE_FILE" | head -n 1)"
    STORED_ICON="$(sed -n 's/^ICON=//p' "$STATE_FILE" | head -n 1)"
    STORED_DERIVED="$(sed -n 's/^DERIVED_ICON=//p' "$STATE_FILE" | head -n 1)"

    [ "$EXPECTED_START" = "$STORED_START" ] || return 1
    [ "$EXPECTED_ICON" = "$STORED_ICON" ] || return 1

    # If icon.png exists, verify the platform-specific derived icon too.
    # If icon.png is absent, icon compatibility is intentionally optional:
    # missing .icns/.ico files do not prevent launch.
    if [ "$ICON_AVAILABLE" -eq 1 ]; then
        [ "$EXPECTED_DERIVED" = "$STORED_DERIVED" ] || return 1
    fi

    return 0
}

write_state()
{
    mkdir -p "$STATE_DIR" || die "Could not create launcher state directory."

    {
        printf 'START=%s\n' "$(current_start_fingerprint)"
        printf 'ICON=%s\n' "$(current_icon_fingerprint)"
        printf 'DERIVED_ICON=%s\n' "$(derived_icon_fingerprint)"
        printf 'PLATFORM=%s\n' "$PLATFORM"
        printf 'INSTALL_DIR=%s\n' "$INSTALL_DIR"
        printf 'INSTALLER_NAME=%s\n' "$INSTALLER_BASENAME"
        printf 'APP_ID=%s\n' "$DESKTOP_APP_ID"
        printf 'APP_NAME=%s\n' "$APP_NAME"
        printf 'CATEGORY=%s\n' "${APP_CATEGORY:-Other}"
        printf 'ICON_SOURCE=%s\n' "$ICON_FILE"
        printf 'LAUNCH_COMMAND=%s\n' "${RZ27_CUSTOM_LAUNCH_COMMAND:-}"
        printf 'SOURCE_SCRIPT=%s\n' "${RZ27_SOURCE_SCRIPT:-}"
        printf 'WORKING_DIRECTORY=%s\n' "${RZ27_CUSTOM_WORKDIR:-}"
    } > "$STATE_FILE" || die "Could not write launcher state."
}

# ------------------------------------------------------------
# Basic helpers
# ------------------------------------------------------------

die()
{
    printf '\nERROR: %s\n\n' "$*" >&2
    exit 1
}

normalize_launch_target()
{
    RAW_TARGET="$1"

    if [ "$PLATFORM" = "windows" ] && command -v cygpath >/dev/null 2>&1; then
        # Accept either native Windows paths (C:\...) or Bash/MSYS paths.
        CONVERTED="$(cygpath -u "$RAW_TARGET" 2>/dev/null || true)"
        if [ -n "$CONVERTED" ]; then
            printf '%s' "$CONVERTED"
            return 0
        fi
    fi

    printf '%s' "$RAW_TARGET"
}

configure_start_for_install()
{
    # A completed install for this exact installer name already owns its own
    # Start.sh. Do not prompt again unless this is a distinct/new install.
    if [ -z "${RZ27_FORCE_RECONFIGURE:-}" ] &&
       [ -f "$STATE_FILE" ] && [ -f "$START_FILE" ]; then
        return 0
    fi

    mkdir -p "$STATE_DIR" ||
        die "Could not create application launcher state directory."

    printf '\n'
    printf '============================================================\n'
    printf ' Installation notice for: %s\n' "$APP_NAME"
    printf '============================================================\n'
    printf '\n'
    printf 'IMPORTANT UNINSTALL LIMITATION:\n'
    printf '\n'
    printf 'This installer can remove the launcher and registration files\n'
    printf 'that IT creates. It cannot automatically remove files, packages,\n'
    printf 'services, drivers, dependencies, settings, or other changes made\n'
    printf 'by the script you choose to launch.\n'
    printf '\n'
    printf 'If the selected script installs additional software, that software\n'
    printf 'must provide or document its own removal method.\n'
    printf '\n'
    printf '============================================================\n'
    printf ' Configure launch target\n'
    printf '============================================================\n'
    printf '\n'
    printf 'Enter the FULL PATH to the script or executable this app\n'
    printf 'should launch.\n'
    printf '\n'
    printf 'Example:\n'
    printf '  /home/user/AItech/AutoKernel.sh\n'
    if [ "$PLATFORM" = "windows" ]; then
        printf '  C:\\Users\\User\\AItech\\AutoKernel.sh\n'
    fi
    printf '\n'
    printf 'Leave this blank to use the generated Start.sh:\n'
    printf '  %s\n' "$START_FILE"
    printf '\n'

    if [ -n "${RZ27_SELECTED_LAUNCH_TARGET:-}" ]; then
        LAUNCH_TARGET="$(normalize_launch_target "$RZ27_SELECTED_LAUNCH_TARGET")"

        if [ ! -e "$LAUNCH_TARGET" ]; then
            die "Manager-selected launch target no longer exists: $RZ27_SELECTED_LAUNCH_TARGET"
        fi

        printf 'Launch path supplied by Installer manager:\n'
        printf '  %s\n\n' "$LAUNCH_TARGET"
    else
        while :; do
            printf 'Launch path [default: Start.sh] (blank or d = default): '
            IFS= read -r RAW_LAUNCH_TARGET || RAW_LAUNCH_TARGET=""

            case "$RAW_LAUNCH_TARGET" in
                ''|d|D)
                    LAUNCH_TARGET="$START_FILE"
                    break
                    ;;
            esac

            LAUNCH_TARGET="$(normalize_launch_target "$RAW_LAUNCH_TARGET")"

            if [ ! -e "$LAUNCH_TARGET" ]; then
                printf '\nThe specified target does not exist:\n'
                printf '  %s\n\n' "$RAW_LAUNCH_TARGET"
                continue
            fi

            break
        done
    fi

    TARGET_Q="$(printf '%q' "$LAUNCH_TARGET")"

    # Start.sh is intentionally generated with cat so it remains a simple,
    # user-editable handoff file.
    #
    # For non-shell targets the Installer manager may provide a custom command
    # such as:
    #   python customapp.py -say
    #
    # The command runs from the selected target's directory so relative file
    # names in that command resolve beside the selected script/application.
    if [ "$LAUNCH_TARGET" = "$START_FILE" ]; then
        cat > "$START_FILE" <<'EOF'
#!/usr/bin/env bash

echo
echo "placeholder, replace with script to run"
echo
EOF
    elif [ -n "${RZ27_CUSTOM_LAUNCH_COMMAND:-}" ]; then
        LAUNCH_DIR="$(cd "$(dirname "$LAUNCH_TARGET")" 2>/dev/null && pwd -P)"
        [ -n "$LAUNCH_DIR" ] || LAUNCH_DIR="$(dirname "$LAUNCH_TARGET")"

        COMMAND_Q="$(printf '%q' "$RZ27_CUSTOM_LAUNCH_COMMAND")"
        LAUNCH_DIR_Q="$(printf '%q' "$LAUNCH_DIR")"

        cat > "$START_FILE" <<EOF
#!/usr/bin/env bash

# ============================================================
# Start.sh for: $APP_NAME
#
# Custom launch command selected during installation.
# Working directory:
#   $LAUNCH_DIR
#
# You may edit LAUNCH_COMMAND manually at any time.
# ============================================================

LAUNCH_DIRECTORY=$LAUNCH_DIR_Q
LAUNCH_COMMAND=$COMMAND_Q

if [ ! -d "\$LAUNCH_DIRECTORY" ]; then
    echo
    echo "LAUNCH FAILED"
    echo "Configured launch directory does not exist:"
    echo "  \$LAUNCH_DIRECTORY"
    echo
    exit 1
fi

cd "\$LAUNCH_DIRECTORY" || exit 1

while :; do
    bash -lc "\$LAUNCH_COMMAND"
    LAUNCH_STATUS=\$?

    if [ "\$LAUNCH_STATUS" -eq 0 ]; then
        exit 0
    fi

    echo
    echo "LAUNCH FAILED"
    echo
    echo "The command used was:"
    echo "  \$LAUNCH_COMMAND"
    echo
    echo "Exit status: \$LAUNCH_STATUS"
    echo
    echo "Input a revised command to continue."
    echo "Leave blank to retry the same command."
    echo "Press q to exit."
    echo
    printf '> '

    IFS= read -r REVISED_COMMAND || exit "\$LAUNCH_STATUS"

    if [ "\$REVISED_COMMAND" = "q" ] || [ "\$REVISED_COMMAND" = "Q" ]; then
        exit "\$LAUNCH_STATUS"
    fi

    if [ -n "\$REVISED_COMMAND" ]; then
        LAUNCH_COMMAND="\$REVISED_COMMAND"
    fi
done
EOF
    else
        cat > "$START_FILE" <<EOF
#!/usr/bin/env bash

# ============================================================
# Start.sh for: $APP_NAME
#
# This file was generated by:
#   $INSTALLER_BASENAME
#
# You may edit SCRIPT_TO_RUN manually at any time.
# Use a full path to the desired script or executable.
# ============================================================

SCRIPT_TO_RUN=$TARGET_Q
LAUNCH_COMMAND="\$SCRIPT_TO_RUN"

while :; do
    if [ ! -e "\$SCRIPT_TO_RUN" ] && [ "\$LAUNCH_COMMAND" = "\$SCRIPT_TO_RUN" ]; then
        LAUNCH_STATUS=127
    else
        if [ "\$LAUNCH_COMMAND" = "\$SCRIPT_TO_RUN" ]; then
            "\$SCRIPT_TO_RUN"
            LAUNCH_STATUS=\$?
        else
            bash -lc "\$LAUNCH_COMMAND"
            LAUNCH_STATUS=\$?
        fi
    fi

    if [ "\$LAUNCH_STATUS" -eq 0 ]; then
        exit 0
    fi

    echo
    echo "LAUNCH FAILED"
    echo
    echo "The command used was:"
    echo "  \$LAUNCH_COMMAND"
    echo
    echo "Exit status: \$LAUNCH_STATUS"
    echo
    echo "Input a revised command to continue."
    echo "Leave blank to retry the same command."
    echo "Press q to exit."
    echo
    printf '> '

    IFS= read -r REVISED_COMMAND || exit "\$LAUNCH_STATUS"

    if [ "\$REVISED_COMMAND" = "q" ] || [ "\$REVISED_COMMAND" = "Q" ]; then
        exit "\$LAUNCH_STATUS"
    fi

    if [ -n "\$REVISED_COMMAND" ]; then
        LAUNCH_COMMAND="\$REVISED_COMMAND"
    fi
done
EOF
    fi

    chmod +x "$START_FILE" 2>/dev/null || true

    {
        printf 'INSTALLER_IDENTITY=%s\n' "$INSTALLER_STEM"
        printf 'APPLICATION_NAME=%s\n' "$APP_NAME"
        printf 'CATEGORY=%s\n' "${APP_CATEGORY:-Other}"
        printf 'LAUNCH_TARGET=%s\n' "$LAUNCH_TARGET"
        printf 'LAUNCH_COMMAND=%s\n' "${RZ27_CUSTOM_LAUNCH_COMMAND:-}"
        printf 'ICON_SOURCE=%s\n' "$ICON_FILE"
        printf 'SOURCE_SCRIPT=%s\n' "${RZ27_SOURCE_SCRIPT:-$LAUNCH_TARGET}"
        printf 'LOCAL_START=%s\n' "$LAUNCH_TARGET"
        printf 'WORKING_DIRECTORY=%s\n' "${RZ27_CUSTOM_WORKDIR:-$(dirname "$LAUNCH_TARGET")}"
        printf 'INSTALL_DIR=%s\n' "$INSTALL_DIR"
        printf 'PLATFORM=%s\n' "$PLATFORM"
    } > "$INSTALL_METADATA_FILE" ||
        die "Could not write install metadata."

    printf '\nConfigured Start.sh:\n'
    printf '  %s\n' "$START_FILE"
    if [ "$LAUNCH_TARGET" = "$START_FILE" ]; then
        printf 'Launch target:\n'
        printf '  Start.sh placeholder (default)\n'
    else
        printf 'Launch target:\n'
        printf '  %s\n' "$LAUNCH_TARGET"
    fi
    printf '\n'
}

emit_default_icon_base64()
