decode_base64_stream_to_file()
{
    OUTPUT_FILE="$1"

    if command -v base64 >/dev/null 2>&1; then
        if emit_default_icon_base64 | base64 -d > "$OUTPUT_FILE" 2>/dev/null; then
            return 0
        fi

        if emit_default_icon_base64 | base64 --decode > "$OUTPUT_FILE" 2>/dev/null; then
            return 0
        fi

        if emit_default_icon_base64 | base64 -D > "$OUTPUT_FILE" 2>/dev/null; then
            return 0
        fi
    fi

    if command -v openssl >/dev/null 2>&1; then
        if emit_default_icon_base64 | openssl base64 -d -A -out "$OUTPUT_FILE" 2>/dev/null; then
            return 0
        fi
    fi

    if command -v python3 >/dev/null 2>&1; then
        emit_default_icon_base64 | python3 - "$OUTPUT_FILE" <<'PYEOF'
import sys, base64, pathlib
pathlib.Path(sys.argv[1]).write_bytes(base64.b64decode(sys.stdin.read()))
PYEOF
        return $?
    fi

    if command -v python >/dev/null 2>&1; then
        emit_default_icon_base64 | python - "$OUTPUT_FILE" <<'PYEOF'
import sys, base64, pathlib
pathlib.Path(sys.argv[1]).write_bytes(base64.b64decode(sys.stdin.read()))
PYEOF
        return $?
    fi

    if command -v powershell.exe >/dev/null 2>&1; then
        TMP_B64="$STATE_DIR/default-icon.b64"
        emit_default_icon_base64 > "$TMP_B64"
        powershell.exe -NoProfile -ExecutionPolicy Bypass -Command \
            "$out=(Resolve-Path '$OUTPUT_FILE'); $b64=(Get-Content -Raw '$TMP_B64'); [IO.File]::WriteAllBytes($out, [Convert]::FromBase64String($b64))" >/dev/null 2>&1
        STATUS=$?
        rm -f "$TMP_B64" 2>/dev/null || true
        return $STATUS
    fi

    return 1
}

bootstrap_default_icon_once()
{
    mkdir -p "$STATE_DIR" 2>/dev/null || true

    # Child installs never synthesize artwork into the selected script's
    # directory. If their chosen/default icon path does not exist they simply
    # install without an icon. The embedded default icon belongs to the
    # persistent Installer manager/bootstrap only.
    if [ -n "${RZ27_MANAGER_CHILD:-}" ]; then
        : > "$ICON_BOOTSTRAP_MARKER"
        return 0
    fi

    # The default icon is only auto-generated during the first bootstrap pass.
    # After that, icon handling becomes fully user-controlled.
    if [ -f "$ICON_BOOTSTRAP_MARKER" ]; then
        return 0
    fi

    if [ ! -f "$ICON_FILE" ]; then
        if decode_base64_stream_to_file "$ICON_FILE"; then
            printf '\nGenerated default icon on first run:\n  %s\n\n' "$ICON_FILE"
        else
            rm -f "$ICON_FILE" 2>/dev/null || true
            printf '\nDefault icon generation was attempted but no decoder was available.\n'
            printf 'Continuing without an icon.\n\n'
        fi
    fi

    : > "$ICON_BOOTSTRAP_MARKER"
}

check_icon()
{
    if [ -f "$ICON_FILE" ]; then
        ICON_AVAILABLE=1
    else
        ICON_AVAILABLE=0
    fi
}

prepare_scripts()
{
    chmod +x "$START_FILE" 2>/dev/null || die "Could not make Start.sh executable."

    if [ -f "$INSTALLER_FILE" ]; then
        chmod +x "$INSTALLER_FILE" 2>/dev/null || true
    fi
}

detect_platform()
{
    UNAME_S="$(uname -s 2>/dev/null || printf 'unknown')"

    case "$UNAME_S" in
        Linux*)
            PLATFORM="linux"
            ;;
        Darwin*)
            PLATFORM="macos"
            ;;
        MINGW*|MSYS*|CYGWIN*)
            PLATFORM="windows"
            ;;
        *)
            die "Unsupported operating system: $UNAME_S"
            ;;
    esac
}

refresh_app_name()
{
    # APP_NAME intentionally follows the actual installer filename, not the
    # installation directory. Nothing needs to be recomputed here.
    :
}

linux_elevation_command()
{
    if command -v sudo >/dev/null 2>&1; then
        printf 'sudo'
        return 0
    fi

    if command -v pkexec >/dev/null 2>&1; then
        printf 'pkexec'
        return 0
    fi

    if command -v doas >/dev/null 2>&1; then
        printf 'doas'
        return 0
    fi

    return 1
}

run_linux_elevated()
{
    if [ "$(id -u)" -eq 0 ]; then
        "$@"
        return $?
    fi

    ELEVATOR="$(linux_elevation_command)" ||
        die "No supported privilege elevation tool was found (sudo, pkexec, or doas)."

    case "$ELEVATOR" in
        sudo)
            sudo -- "$@"
            ;;
        pkexec)
            pkexec "$@"
            ;;
        doas)
            doas -- "$@"
            ;;
    esac
}

prepare_platform_icon()
{
    # Icons remain optional after first-run bootstrap. If the user has
    # intentionally removed icon.png, do not recreate it here.
    [ "$ICON_AVAILABLE" -eq 1 ] || return 0

    case "$PLATFORM" in
        linux)
            # Freedesktop/Linux uses PNG; install_linux_launcher copies it
            # into the system hicolor icon theme.
            [ -f "$ICON_FILE" ] || return 1
            ;;
        macos)
            # macOS launcher bundles use ICNS.
            mac_paths
            mac_make_icns
            [ -f "$MAC_ICON" ] || return 1
            ;;
        windows)
            # Windows shortcuts use ICO.
            windows_make_icon
            [ -f "$WIN_ICON" ] || return 1
            ;;
    esac

    return 0
}

# ============================================================
# LINUX
# ============================================================

linux_desktop_file()
{
    # System-wide freedesktop locations. /usr/share is the standard datadir
    # for applications installed by root.
    LINUX_APPLICATIONS_DIR="/usr/share/applications"
    LINUX_DESKTOP_FILE="$LINUX_APPLICATIONS_DIR/$DESKTOP_APP_ID.desktop"

    # Install the PNG under the hicolor icon theme and refer to it by icon
    # name from the desktop entry.
    LINUX_ICON_DIR="/usr/share/icons/hicolor/512x512/apps"
    LINUX_SYSTEM_ICON="$LINUX_ICON_DIR/$DESKTOP_APP_ID.png"

    # A real system command is installed so the system-wide .desktop entry
    # does not point directly into a hidden/private home-directory path.
    LINUX_SYSTEM_WRAPPER="/usr/local/bin/$DESKTOP_APP_ID-launcher"

    # Cleanup targets from older per-user versions of this installer.
    LINUX_USER_APPLICATIONS_DIR="${XDG_DATA_HOME:-$HOME/.local/share}/applications"
    LINUX_OLD_USER_DESKTOP="$LINUX_USER_APPLICATIONS_DIR/$APP_ID.desktop"
    LINUX_NAMESPACED_USER_DESKTOP="$LINUX_USER_APPLICATIONS_DIR/$DESKTOP_APP_ID.desktop"
    LINUX_LEGACY_USER_DESKTOP="$LINUX_USER_APPLICATIONS_DIR/$LEGACY_APP_ID.desktop"

    # Previous system-wide revisions used an un-namespaced ID.
    LINUX_OLD_SYSTEM_DESKTOP="$LINUX_APPLICATIONS_DIR/$APP_ID.desktop"
    LINUX_OLD_SYSTEM_ICON="$LINUX_ICON_DIR/$APP_ID.png"
    LINUX_OLD_SYSTEM_WRAPPER="/usr/local/bin/$APP_ID-launcher"
}

generate_linux_system_wrapper()
{
    Q_START_DIR="$(printf "%s" "$(dirname "$START_FILE")" | sed "s/'/'\\''/g")"
    Q_START="$(printf "%s" "$START_FILE" | sed "s/'/'\\''/g")"

    cat <<EOF
#!/usr/bin/env bash
cd '$Q_START_DIR' || exit 1
exec '$Q_START'
EOF
}

generate_linux_desktop()
{
    cat <<EOF
[Desktop Entry]
Version=1.0
Type=Application
Name=$APP_NAME
Comment=Launch $APP_NAME
Path=$INSTALL_DIR
Exec=$LINUX_SYSTEM_WRAPPER
TryExec=$LINUX_SYSTEM_WRAPPER
EOF

    if [ "$ICON_AVAILABLE" -eq 1 ]; then
        printf 'Icon=%s\n' "$DESKTOP_APP_ID"
    fi

    cat <<'EOF'
Terminal=true
StartupNotify=true
EOF

    if [ -n "$APP_CATEGORY" ]; then
        printf 'Categories=%s;\n' "$APP_CATEGORY"
    fi
}

linux_launcher_is_current()
{
    linux_desktop_file

    [ -f "$LINUX_DESKTOP_FILE" ] || return 1
    [ -x "$LINUX_SYSTEM_WRAPPER" ] || return 1

    TMP_EXPECTED="$(mktemp)" || return 1
    generate_linux_desktop > "$TMP_EXPECTED"

    TMP_EXPECTED_WRAPPER="$(mktemp)" || {
        rm -f "$TMP_EXPECTED"
        return 1
    }
    generate_linux_system_wrapper > "$TMP_EXPECTED_WRAPPER"

    if cmp -s "$TMP_EXPECTED" "$LINUX_DESKTOP_FILE" &&
       cmp -s "$TMP_EXPECTED_WRAPPER" "$LINUX_SYSTEM_WRAPPER"; then
        rm -f "$TMP_EXPECTED" "$TMP_EXPECTED_WRAPPER"

        if [ "$ICON_AVAILABLE" -eq 1 ]; then
            [ -f "$LINUX_SYSTEM_ICON" ] || return 1
            [ "$(file_fingerprint "$ICON_FILE")" = "$(file_fingerprint "$LINUX_SYSTEM_ICON")" ] || return 1
        fi

        # No cache/launcher refresh is needed unless Start.sh or icon state
        # has actually changed since the last successful install.
        state_is_current || return 1

        return 0
    fi

    rm -f "$TMP_EXPECTED" "$TMP_EXPECTED_WRAPPER"
    return 1
}

linux_launcher_registered()
{
    linux_desktop_file

    [ -f "$LINUX_DESKTOP_FILE" ] || return 1

    # Prefer GLib/GIO application discovery because Pantheon/elementary,
    # GNOME-family desktops, Cinnamon, MATE, Xfce integrations and many
    # other freedesktop menus consume this application registry.
    #
    # Gio.AppInfo.get_all() returns desktop application entries known to
    # GLib. We require both the matching desktop ID and should_show()=true,
    # so first run only completes when the entry is actually displayable.
    if command -v python3 >/dev/null 2>&1; then
        if python3 - "$DESKTOP_APP_ID.desktop" <<'PY' >/dev/null 2>&1
import sys
wanted = sys.argv[1]
try:
    import gi
    gi.require_version("Gio", "2.0")
    from gi.repository import Gio
except Exception:
    sys.exit(2)

for app in Gio.AppInfo.get_all():
    try:
        app_id = app.get_id()
        visible = app.should_show()
    except Exception:
        continue
    if app_id == wanted and visible:
        sys.exit(0)

sys.exit(1)
PY
        then
            return 0
        else
            RC=$?
            # RC=2 means Python GI is not installed; continue to fallbacks.
            [ "$RC" -ne 2 ] && return 1
        fi
    fi

    # Fallback: gtk-launch resolves desktop IDs through the desktop
    # application database. --help is used only to establish that the tool
    # exists; we do not launch the application during verification.
    #
    # Since gtk-launch has no query-only mode, the portable fallback is to
    # verify that the desktop file resides in an XDG applications directory,
    # is valid if validation tooling exists, and that the current XDG search
    # path includes the directory.
    if command -v desktop-file-validate >/dev/null 2>&1; then
        desktop-file-validate "$LINUX_DESKTOP_FILE" >/dev/null 2>&1 || return 1
    fi

    case ":${XDG_DATA_DIRS:-/usr/local/share:/usr/share}:" in
        *":$HOME/.local/share:"*|*)
            # Per-user applications are defined by XDG_DATA_HOME, which is
            # always searched before XDG_DATA_DIRS by compliant desktops.
            ;;
    esac

    [ -r "$LINUX_DESKTOP_FILE" ]
}

linux_is_pantheon()
{
    DESKTOPS="${XDG_CURRENT_DESKTOP:-}"

    case ":$DESKTOPS:" in
        *:Pantheon:*|*:pantheon:*)
            return 0
            ;;
    esac

    # elementary sessions may expose Pantheon through DESKTOP_SESSION.
    case "${DESKTOP_SESSION:-}" in
        *pantheon*|*Pantheon*)
            return 0
            ;;
    esac

    return 1
}

pantheon_dock_has_launcher()
{
    linux_is_pantheon || return 1
    command -v gsettings >/dev/null 2>&1 || return 1

    gsettings get io.elementary.dock launchers 2>/dev/null |
        grep -Fq "'$DESKTOP_APP_ID.desktop'"
}

pantheon_add_launcher_to_dock()
{
    linux_is_pantheon || return 0
    command -v gsettings >/dev/null 2>&1 || return 0
    command -v python3 >/dev/null 2>&1 || return 0

    gsettings get io.elementary.dock launchers >/dev/null 2>&1 || return 0
    pantheon_dock_has_launcher && return 0

    NEW_LAUNCHERS="$(
        python3 - "$DESKTOP_APP_ID.desktop" <<'PY'
import ast
import subprocess
import sys

desktop_id = sys.argv[1]
try:
    raw = subprocess.check_output(
        ["gsettings", "get", "io.elementary.dock", "launchers"],
        text=True
    ).strip()
    launchers = ast.literal_eval(raw)
except Exception:
    sys.exit(1)

if desktop_id not in launchers:
    launchers.append(desktop_id)

print(repr(launchers))
PY
    )" || return 0

    [ -n "$NEW_LAUNCHERS" ] || return 0
    gsettings set io.elementary.dock launchers "$NEW_LAUNCHERS" >/dev/null 2>&1 || true
    return 0
}

pantheon_remove_launcher_from_dock()
{
    linux_is_pantheon || return 0
    command -v gsettings >/dev/null 2>&1 || return 0
    command -v python3 >/dev/null 2>&1 || return 0

    gsettings get io.elementary.dock launchers >/dev/null 2>&1 || return 0

    NEW_LAUNCHERS="$(
        python3 - "$DESKTOP_APP_ID.desktop" <<'PY'
import ast
import subprocess
import sys

desktop_id = sys.argv[1]
try:
    raw = subprocess.check_output(
        ["gsettings", "get", "io.elementary.dock", "launchers"],
        text=True
    ).strip()
    launchers = ast.literal_eval(raw)
except Exception:
    sys.exit(1)

launchers = [item for item in launchers if item != desktop_id]
print(repr(launchers))
PY
    )" || return 0

    [ -n "$NEW_LAUNCHERS" ] || return 0
    gsettings set io.elementary.dock launchers "$NEW_LAUNCHERS" >/dev/null 2>&1 || true
    return 0
}

refresh_pantheon_dock()
{
    linux_is_pantheon || return 0

    if command -v pkill >/dev/null 2>&1; then
        pkill -TERM -x io.elementary.dock >/dev/null 2>&1 || true
    elif command -v killall >/dev/null 2>&1; then
        killall io.elementary.dock >/dev/null 2>&1 || true
    fi

    sleep 2
    return 0
}

refresh_pantheon_applications_menu()
{
    linux_is_pantheon || return 0

    printf 'Refreshing Pantheon Applications Menu...\n'

    # Prefer a user systemd unit when the session exposes one. This restarts
    # only the current user's panel/menu process, never the whole desktop.
    if command -v systemctl >/dev/null 2>&1; then
        if systemctl --user status io.elementary.wingpanel.service \
            >/dev/null 2>&1; then
            systemctl --user restart io.elementary.wingpanel.service \
                >/dev/null 2>&1 || true
            sleep 2
            return 0
        fi

        if systemctl --user status wingpanel.service \
            >/dev/null 2>&1; then
            systemctl --user restart wingpanel.service \
                >/dev/null 2>&1 || true
            sleep 2
            return 0
        fi
    fi

    # Wingpanel hosts elementary's Applications Menu. When it is not managed
    # by a visible user systemd unit, terminate the user's existing process;
    # Pantheon's session normally respawns it automatically.
    if command -v pkill >/dev/null 2>&1; then
        pkill -TERM -x io.elementary.wingpanel >/dev/null 2>&1 || \
        pkill -TERM -x wingpanel >/dev/null 2>&1 || true
        sleep 2
    elif command -v killall >/dev/null 2>&1; then
        killall io.elementary.wingpanel >/dev/null 2>&1 || \
        killall wingpanel >/dev/null 2>&1 || true
        sleep 2
    fi

    return 0
}

verify_linux_launcher_registration()
{
    # Give GLib/menu monitors a few short opportunities to notice a newly
    # created application entry. This is synchronous; first run is not
    # marked complete unless one of these checks succeeds.
    ATTEMPT=1
    while [ "$ATTEMPT" -le 5 ]; do
        if linux_launcher_registered; then
            return 0
        fi

        if command -v xdg-desktop-menu >/dev/null 2>&1; then
            xdg-desktop-menu forceupdate >/dev/null 2>&1 || true
        fi

        if command -v update-desktop-database >/dev/null 2>&1; then
            update-desktop-database "$LINUX_APPLICATIONS_DIR" >/dev/null 2>&1 || true
        fi

        sleep 1
        ATTEMPT=$((ATTEMPT + 1))
    done

    return 1
}

install_linux_launcher()
{
    linux_desktop_file

    TMP_LINUX_DIR="$(mktemp -d)" ||
        die "Could not create temporary Linux desktop directory."

    TMP_LINUX_DESKTOP="$TMP_LINUX_DIR/$DESKTOP_APP_ID.desktop"

    generate_linux_desktop > "$TMP_LINUX_DESKTOP" ||
        die "Could not generate Linux desktop entry."

    # Validate before privileged installation when desktop-file-utils exists.
    # minimal distributions are still supported when the utility is absent.
    if command -v desktop-file-validate >/dev/null 2>&1; then
        if ! desktop-file-validate "$TMP_LINUX_DESKTOP"; then
            rm -rf "$TMP_LINUX_DIR"
            die "Generated Linux desktop launcher failed desktop-file validation."
        fi
    fi

    TMP_LINUX_WRAPPER="$(mktemp)" ||
        die "Could not create temporary Linux launcher wrapper."

    generate_linux_system_wrapper > "$TMP_LINUX_WRAPPER" ||
        die "Could not generate Linux launcher wrapper."

    run_linux_elevated mkdir -p "$LINUX_APPLICATIONS_DIR" ||
        die "Could not create system applications directory."

    run_linux_elevated mkdir -p "$(dirname "$LINUX_SYSTEM_WRAPPER")" ||
        die "Could not create system launcher directory."

    run_linux_elevated install -m 0755 "$TMP_LINUX_WRAPPER" "$LINUX_SYSTEM_WRAPPER" ||
        die "Could not install system launcher wrapper."

    rm -f "$TMP_LINUX_WRAPPER"

    # Prefer xdg-desktop-menu because it is specifically intended to
    # integrate third-party application launchers with XDG desktop menus.
    # Fall back to desktop-file-install, then to a direct standards-compliant
    # copy when those utilities are unavailable.
    if command -v xdg-desktop-menu >/dev/null 2>&1; then
        run_linux_elevated xdg-desktop-menu install --mode system --novendor "$TMP_LINUX_DESKTOP" ||
            die "xdg-desktop-menu could not install the system menu entry."
    elif command -v desktop-file-install >/dev/null 2>&1; then
        run_linux_elevated desktop-file-install             --dir="$LINUX_APPLICATIONS_DIR"             "$TMP_LINUX_DESKTOP" ||
            die "desktop-file-install could not install the system menu entry."
    else
        run_linux_elevated install -m 0644 "$TMP_LINUX_DESKTOP" "$LINUX_DESKTOP_FILE" ||
            die "Could not install system-wide desktop launcher."
    fi

    # Ensure the canonical expected path exists even when an xdg-utils
    # implementation chooses to normalize installation details.
    if [ ! -f "$LINUX_DESKTOP_FILE" ]; then
        run_linux_elevated install -m 0644 "$TMP_LINUX_DESKTOP" "$LINUX_DESKTOP_FILE" ||
            die "Could not establish canonical system desktop entry."
    fi

    rm -rf "$TMP_LINUX_DIR"

    if [ "$ICON_AVAILABLE" -eq 1 ]; then
        run_linux_elevated mkdir -p "$LINUX_ICON_DIR" ||
            die "Could not create system icon directory."
        run_linux_elevated install -m 0644 "$ICON_FILE" "$LINUX_SYSTEM_ICON" ||
            die "Could not install system-wide PNG icon."
    else
        run_linux_elevated rm -f "$LINUX_SYSTEM_ICON" >/dev/null 2>&1 || true
    fi

    # Remove stale per-user entries that would shadow the system-wide entry.
    rm -f "$LINUX_OLD_USER_DESKTOP" "$LINUX_NAMESPACED_USER_DESKTOP" 2>/dev/null || true
    if [ "$LINUX_LEGACY_USER_DESKTOP" != "$LINUX_OLD_USER_DESKTOP" ]; then
        rm -f "$LINUX_LEGACY_USER_DESKTOP" 2>/dev/null || true
    fi

    run_linux_elevated rm -f         "$LINUX_OLD_SYSTEM_DESKTOP"         "$LINUX_OLD_SYSTEM_ICON"         "$LINUX_OLD_SYSTEM_WRAPPER" >/dev/null 2>&1 || true

    # update-desktop-database rebuilds MIME/application metadata on desktops
    # that provide desktop-file-utils.
    if command -v update-desktop-database >/dev/null 2>&1; then
        update-desktop-database "$LINUX_APPLICATIONS_DIR" >/dev/null 2>&1 || true
    fi

    # Pantheon/elementary, GNOME-family, Xfce, Cinnamon, MATE and other
    # freedesktop menus commonly observe XDG application directories.
    # If xdg-utils provides an explicit menu refresh, request one.
    if command -v xdg-desktop-menu >/dev/null 2>&1; then
        xdg-desktop-menu forceupdate >/dev/null 2>&1 || true
    fi

    # Some GLib-based desktops track trust metadata. This is harmless when
    # unsupported and is not required for distributions that ignore it.
    if [ "$ICON_AVAILABLE" -eq 1 ] && command -v gtk-update-icon-cache >/dev/null 2>&1; then
        run_linux_elevated gtk-update-icon-cache -f -t /usr/share/icons/hicolor >/dev/null 2>&1 || true
    fi

    # elementary OS/Pantheon may keep an already-running Applications
    # Menu list in memory even after the freedesktop databases are updated.
    # Refresh the user's Wingpanel/menu before final verification.
    refresh_pantheon_applications_menu

    # elementary OS 8 has known cases where a valid installed desktop entry
    # is absent from the Applications Menu grid. Register it with the Dock as
    # an additional native launch surface so the app is immediately usable.
    if linux_is_pantheon; then
        pantheon_add_launcher_to_dock
        refresh_pantheon_dock
    fi

    printf '\nVerifying system-wide application-menu registration...\n'

    if verify_linux_launcher_registration; then
        write_state
    rz27_registry_add_current
        printf 'Application registration verified and menu refresh completed.\n'
    else
        # Deliberately do NOT write install.state here. Without that state,
        # first run remains incomplete and the next invocation retries the
        # launcher registration process instead of launching Start.sh.
        printf '\n'
        printf 'Launcher file was created, but application-menu registration\n'
        printf 'could not be verified yet.\n'
        printf '\n'
        printf 'First run remains incomplete.\n'
        printf 'Run this installer again after the desktop session has noticed\n'
        printf 'the new application entry.\n'
        printf '\n'
        return 1
    fi

    printf '\nInstalled/updated Linux launcher:\n  %s\n\n' "$LINUX_DESKTOP_FILE"
}

run_linux_start()
{
    cd "$INSTALL_DIR" || exit 1

    ELEVATOR="$(linux_elevation_command)" ||
        die "No supported privilege elevation tool was found (sudo, pkexec, or doas)."

    case "$ELEVATOR" in
        sudo)
            exec sudo -- "$START_FILE"
            ;;
        pkexec)
            # Preserve the intended working directory explicitly because
            # pkexec may sanitize parts of the environment.
            exec pkexec env "PATH=$PATH" bash -c 'cd "$1" && exec "$2"' _ "$INSTALL_DIR" "$START_FILE"
            ;;
        doas)
            exec doas -- "$START_FILE"
            ;;
    esac
}

# ============================================================
# macOS 10.13+
# ============================================================

run_mac_elevated()
{
    if [ "$(id -u)" -eq 0 ]; then
        "$@"
    else
        sudo -- "$@"
    fi
}

mac_launchservices_register()
{
    LSREGISTER="/System/Library/Frameworks/CoreServices.framework/Frameworks/LaunchServices.framework/Support/lsregister"

    if [ -x "$LSREGISTER" ]; then
        "$LSREGISTER" -f "$MAC_APP_DIR" >/dev/null 2>&1 || true
    fi

    # Touching /Applications and the bundle helps Finder/LaunchServices notice
    # a newly installed app on older macOS releases as well.
    touch "$MAC_APP_DIR" 2>/dev/null || true
    touch /Applications 2>/dev/null || true
}

mac_launcher_registered()
{
    [ -d "$MAC_APP_DIR" ] || return 1

    # Ask LaunchServices to resolve the installed application.
    if command -v open >/dev/null 2>&1; then
        open -Ra "$APP_NAME" >/dev/null 2>&1 && return 0
    fi

    # Fallback: a valid app bundle in /Applications is considered installed.
    [ -x "$MAC_LAUNCHER" ] && [ -f "$MAC_PLIST" ]
}

mac_paths()
{
    MAC_APP_DIR="/Applications/$APP_NAME.app"
    MAC_CONTENTS="$MAC_APP_DIR/Contents"
    MAC_MACOS="$MAC_CONTENTS/MacOS"
    MAC_RESOURCES="$MAC_CONTENTS/Resources"
    MAC_LAUNCHER="$MAC_MACOS/launcher"
    MAC_PLIST="$MAC_CONTENTS/Info.plist"
    MAC_ICON="$MAC_RESOURCES/icon.icns"
}

mac_shell_quote()
{
    # Single-quote a string for a POSIX shell command.
    printf "'%s'" "$(printf '%s' "$1" | sed "s/'/'\\\\''/g")"
}

generate_mac_launcher()
{
    Q_START="$(mac_shell_quote "$START_FILE")"
    Q_START_DIR="$(mac_shell_quote "$(dirname "$START_FILE")")"

    cat <<EOF
#!/usr/bin/env bash
COMMAND="cd $Q_START_DIR && $Q_START"
osascript - "\$COMMAND" <<'APPLESCRIPT'
on run argv
    set shellCommand to item 1 of argv
    tell application "Terminal"
        activate
        do script shellCommand
    end tell
end run
APPLESCRIPT
EOF
}

generate_mac_plist()
{
    SAFE_NAME="$(printf '%s' "$APP_NAME" |
        sed 's/&/\&amp;/g; s/</\&lt;/g; s/>/\&gt;/g')"

    cat <<EOF
<?xml version="1.0" encoding="UTF-8"?>
<!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN"
  "http://www.apple.com/DTDs/PropertyList-1.0.dtd">
<plist version="1.0">
<dict>
    <key>CFBundleName</key>
    <string>$SAFE_NAME</string>
    <key>CFBundleDisplayName</key>
    <string>$SAFE_NAME</string>
    <key>CFBundleExecutable</key>
    <string>launcher</string>
    <key>CFBundleIdentifier</key>
    <string>local.$APP_ID.launcher</string>
    <key>CFBundlePackageType</key>
    <string>APPL</string>
EOF

    case "$APP_CATEGORY" in
        Utility|System)
            printf '    <key>LSApplicationCategoryType</key>\n'
            printf '    <string>public.app-category.utilities</string>\n'
            ;;
        Development)
            printf '    <key>LSApplicationCategoryType</key>\n'
            printf '    <string>public.app-category.developer-tools</string>\n'
            ;;
        Graphics)
            printf '    <key>LSApplicationCategoryType</key>\n'
            printf '    <string>public.app-category.graphics-design</string>\n'
            ;;
        Game)
            printf '    <key>LSApplicationCategoryType</key>\n'
            printf '    <string>public.app-category.games</string>\n'
            ;;
        Education)
            printf '    <key>LSApplicationCategoryType</key>\n'
            printf '    <string>public.app-category.education</string>\n'
            ;;
        Office)
            printf '    <key>LSApplicationCategoryType</key>\n'
            printf '    <string>public.app-category.productivity</string>\n'
            ;;
    esac

    if [ "$ICON_AVAILABLE" -eq 1 ]; then
        cat <<'EOF'
    <key>CFBundleIconFile</key>
    <string>icon.icns</string>
EOF
    fi

    cat <<'EOF'
</dict>
</plist>
EOF
}

mac_make_icns()
{
    command -v sips >/dev/null 2>&1 ||
        die "macOS utility 'sips' is unavailable."
    command -v iconutil >/dev/null 2>&1 ||
        die "macOS utility 'iconutil' is unavailable."

    TMP_ICONSET="$(mktemp -d)/icon.iconset" || exit 1
    mkdir -p "$TMP_ICONSET" || exit 1

    # iconutil expects these canonical iconset names.
    sips -z 16 16     "$ICON_FILE" --out "$TMP_ICONSET/icon_16x16.png" >/dev/null
    sips -z 32 32     "$ICON_FILE" --out "$TMP_ICONSET/icon_16x16@2x.png" >/dev/null
    sips -z 32 32     "$ICON_FILE" --out "$TMP_ICONSET/icon_32x32.png" >/dev/null
    sips -z 64 64     "$ICON_FILE" --out "$TMP_ICONSET/icon_32x32@2x.png" >/dev/null
    sips -z 128 128   "$ICON_FILE" --out "$TMP_ICONSET/icon_128x128.png" >/dev/null
    sips -z 256 256   "$ICON_FILE" --out "$TMP_ICONSET/icon_128x128@2x.png" >/dev/null
    sips -z 256 256   "$ICON_FILE" --out "$TMP_ICONSET/icon_256x256.png" >/dev/null
    sips -z 512 512   "$ICON_FILE" --out "$TMP_ICONSET/icon_256x256@2x.png" >/dev/null
    sips -z 512 512   "$ICON_FILE" --out "$TMP_ICONSET/icon_512x512.png" >/dev/null
    sips -z 1024 1024 "$ICON_FILE" --out "$TMP_ICONSET/icon_512x512@2x.png" >/dev/null

    iconutil -c icns "$TMP_ICONSET" -o "$MAC_ICON" ||
        die "Could not create macOS icon.icns."

    rm -rf "$(dirname "$TMP_ICONSET")"
}

mac_launcher_is_current()
{
    mac_paths

    [ -f "$MAC_LAUNCHER" ] || return 1
    [ -f "$MAC_PLIST" ] || return 1

    if [ "$ICON_AVAILABLE" -eq 1 ]; then
        [ -f "$MAC_ICON" ] || return 1
    fi

    TMP_DIR="$(mktemp -d)" || return 1
    generate_mac_launcher > "$TMP_DIR/launcher"
    generate_mac_plist > "$TMP_DIR/Info.plist"

    if cmp -s "$TMP_DIR/launcher" "$MAC_LAUNCHER" &&
       cmp -s "$TMP_DIR/Info.plist" "$MAC_PLIST"; then
        rm -rf "$TMP_DIR"

        state_is_current || return 1

        return 0
    fi

    rm -rf "$TMP_DIR"
    return 1
}

install_mac_launcher()
{
    mac_paths

    FINAL_MAC_APP_DIR="$MAC_APP_DIR"
    FINAL_MAC_CONTENTS="$MAC_CONTENTS"
    FINAL_MAC_MACOS="$MAC_MACOS"
    FINAL_MAC_RESOURCES="$MAC_RESOURCES"
    FINAL_MAC_LAUNCHER="$MAC_LAUNCHER"
    FINAL_MAC_PLIST="$MAC_PLIST"
    FINAL_MAC_ICON="$MAC_ICON"

    TMP_MAC_ROOT="$(mktemp -d)" || die "Could not create temporary macOS bundle."
    MAC_APP_DIR="$TMP_MAC_ROOT/$APP_NAME.app"
    MAC_CONTENTS="$MAC_APP_DIR/Contents"
    MAC_MACOS="$MAC_CONTENTS/MacOS"
    MAC_RESOURCES="$MAC_CONTENTS/Resources"
    MAC_LAUNCHER="$MAC_MACOS/launcher"
    MAC_PLIST="$MAC_CONTENTS/Info.plist"
    MAC_ICON="$MAC_RESOURCES/icon.icns"

    mkdir -p "$MAC_MACOS" "$MAC_RESOURCES" ||
        die "Could not create temporary macOS application bundle."

    generate_mac_launcher > "$MAC_LAUNCHER" ||
        die "Could not create macOS launcher."

    generate_mac_plist > "$MAC_PLIST" ||
        die "Could not create macOS Info.plist."

    chmod +x "$MAC_LAUNCHER" ||
        die "Could not make macOS launcher executable."

    if [ "$ICON_AVAILABLE" -eq 1 ]; then
        mac_make_icns || die "Could not generate the macOS ICNS icon."
    fi

    MAC_APP_DIR="$FINAL_MAC_APP_DIR"
    MAC_CONTENTS="$FINAL_MAC_CONTENTS"
    MAC_MACOS="$FINAL_MAC_MACOS"
    MAC_RESOURCES="$FINAL_MAC_RESOURCES"
    MAC_LAUNCHER="$FINAL_MAC_LAUNCHER"
    MAC_PLIST="$FINAL_MAC_PLIST"
    MAC_ICON="$FINAL_MAC_ICON"

    run_mac_elevated rm -rf "$MAC_APP_DIR" ||
        die "Could not replace existing macOS application."

    run_mac_elevated cp -R "$TMP_MAC_ROOT/$APP_NAME.app" "$MAC_APP_DIR" ||
        die "Could not install application into /Applications."

    rm -rf "$TMP_MAC_ROOT"

    mac_launchservices_register

    if ! mac_launcher_registered; then
        die "macOS application bundle was installed but LaunchServices could not verify it."
    fi

    write_state
    rz27_registry_add_current

    printf '\nInstalled/updated macOS system application:\n  %s\n\n' "$MAC_APP_DIR"
}

run_macos_start()
{
    cd "$INSTALL_DIR" || exit 1

    # The .app opens this installer inside Terminal first, so sudo prompts
    # in the Terminal window just as a manual sudo invocation would.
    exec sudo -- "$START_FILE"
}

# ============================================================
# WINDOWS 8.1 / 10 / 11
# Requires Bash (normally Git for Windows, MSYS2, or Cygwin).
# ============================================================

windows_find_powershell()
{
    if command -v powershell.exe >/dev/null 2>&1; then
        POWERSHELL_EXE="$(command -v powershell.exe)"
    elif command -v powershell >/dev/null 2>&1; then
        POWERSHELL_EXE="$(command -v powershell)"
    else
        die "Windows PowerShell was not found."
    fi
}

windows_to_native()
{
    INPUT_PATH="$1"

    if command -v cygpath >/dev/null 2>&1; then
        cygpath -w "$INPUT_PATH"
    else
        printf '%s' "$INPUT_PATH"
    fi
}

windows_find_bash()
{
    BASH_POSIX="$(command -v bash 2>/dev/null || true)"
    [ -n "$BASH_POSIX" ] || die "bash could not be located."

    BASH_NATIVE="$(windows_to_native "$BASH_POSIX")"
}

windows_paths()
{
    windows_find_powershell
    windows_find_bash

    WIN_INSTALL_NATIVE="$(windows_to_native "$INSTALL_DIR")"
    WIN_INSTALLER_NATIVE="$(windows_to_native "$INSTALLER_FILE")"
    WIN_START_NATIVE="$(windows_to_native "$START_FILE")"
    WIN_ICON_PNG_NATIVE="$(windows_to_native "$ICON_FILE")"

    # Use the all-users Start Menu Programs folder so the app is visible
    # system-wide on Windows 8.1, 10, and 11.
    WIN_PROGRAMS_NATIVE="$("$POWERSHELL_EXE" -NoProfile -Command \
        "[Environment]::GetFolderPath('CommonPrograms')" 2>/dev/null |
        tr -d '\r')"

    [ -n "$WIN_PROGRAMS_NATIVE" ] ||
        die "Could not determine the Windows all-users Start Menu Programs directory."

    if command -v cygpath >/dev/null 2>&1; then
        WIN_PROGRAMS_POSIX="$(cygpath -u "$WIN_PROGRAMS_NATIVE")"
    else
        WIN_PROGRAMS_POSIX="$WIN_PROGRAMS_NATIVE"
    fi

    WIN_SHORTCUT_NATIVE="$WIN_PROGRAMS_NATIVE\\$INSTALLER_STEM.lnk"
    WIN_SHORTCUT_POSIX="$WIN_PROGRAMS_POSIX/$INSTALLER_STEM.lnk"

    WIN_SUPPORT_DIR="$STATE_DIR"
    WIN_RUNNER="$WIN_SUPPORT_DIR/windows-run.cmd"
    WIN_ICON="$WIN_SUPPORT_DIR/icon.ico"
    WIN_UNINSTALLER="$WIN_SUPPORT_DIR/${INSTALLER_STEM}-uninstall.sh"

    WIN_RUNNER_NATIVE="$(windows_to_native "$WIN_RUNNER")"
    WIN_ICON_NATIVE="$(windows_to_native "$WIN_ICON")"
    WIN_UNINSTALLER_NATIVE="$(windows_to_native "$WIN_UNINSTALLER")"

    WIN_UNINSTALL_KEY="HKLM:\\Software\\Microsoft\\Windows\\CurrentVersion\\Uninstall\\RZ27-$APP_ID"
}

windows_shortcut_registered()
{
    windows_paths

    SHORTCUT_PS="$(windows_escape_ps_single "$WIN_SHORTCUT_NATIVE")"

    RESULT="$("$POWERSHELL_EXE" -NoProfile -Command \
        "if (Test-Path -LiteralPath '$SHORTCUT_PS') { 'yes' } else { 'no' }" \
        2>/dev/null | tr -d '\r')"

    [ "$RESULT" = "yes" ]
}

generate_windows_runner()
{
    START_NATIVE="$(windows_to_native "$START_FILE")"
    START_DIR_NATIVE="$(windows_to_native "$(dirname "$START_FILE")")"

    cat <<EOF
@echo off
cd /d "$START_DIR_NATIVE"
"$BASH_NATIVE" "$START_NATIVE"
EOF
}

windows_escape_ps_single()
{
    printf '%s' "$1" | sed "s/'/''/g"
}

windows_make_icon()
{
    windows_paths
    mkdir -p "$WIN_SUPPORT_DIR" || die "Could not create $WIN_SUPPORT_DIR"

    PNG_PS="$(windows_escape_ps_single "$WIN_ICON_PNG_NATIVE")"
    ICO_PS="$(windows_escape_ps_single "$WIN_ICON_NATIVE")"

    "$POWERSHELL_EXE" -NoProfile -ExecutionPolicy Bypass -Command \
        "Add-Type -AssemblyName System.Drawing; \
         \$bmp = New-Object System.Drawing.Bitmap('$PNG_PS'); \
         \$h = \$bmp.GetHicon(); \
         \$ico = [System.Drawing.Icon]::FromHandle(\$h); \
         \$fs = [System.IO.File]::Open('$ICO_PS',[System.IO.FileMode]::Create); \
         \$ico.Save(\$fs); \
         \$fs.Close(); \
         \$ico.Dispose(); \
         \$bmp.Dispose()" >/dev/null 2>&1 || {
            # Icon conversion failure should not prevent installation.
            rm -f "$WIN_ICON" 2>/dev/null || true
            return 1
        }

    touch "$WIN_ICON" 2>/dev/null || true
    return 0
}

windows_shortcut_matches()
{
    windows_paths

    [ -f "$WIN_SHORTCUT_POSIX" ] || return 1
    [ -f "$WIN_RUNNER" ] || return 1

    TMP_EXPECTED="$(mktemp)" || return 1
    generate_windows_runner > "$TMP_EXPECTED"

    if ! cmp -s "$TMP_EXPECTED" "$WIN_RUNNER"; then
        rm -f "$TMP_EXPECTED"
        return 1
    fi
    rm -f "$TMP_EXPECTED"

    SHORTCUT_PS="$(windows_escape_ps_single "$WIN_SHORTCUT_NATIVE")"
    RUNNER_PS="$(windows_escape_ps_single "$WIN_RUNNER_NATIVE")"
    INSTALL_PS="$(windows_escape_ps_single "$WIN_INSTALL_NATIVE")"

    MATCH="$("$POWERSHELL_EXE" -NoProfile -Command \
        "\$w=New-Object -ComObject WScript.Shell; \
         \$s=\$w.CreateShortcut('$SHORTCUT_PS'); \
         if ((\$s.TargetPath -ieq '$RUNNER_PS') -and \
             (\$s.WorkingDirectory -ieq '$INSTALL_PS')) { 'yes' } else { 'no' }" \
        2>/dev/null | tr -d '\r')"

    [ "$MATCH" = "yes" ] || return 1

    # If icon.png is being used, verify the generated ICO exists.
    # Otherwise icon compatibility is intentionally optional.
    if [ "$ICON_AVAILABLE" -eq 1 ]; then
        [ -f "$WIN_ICON" ] || return 1
    fi

    state_is_current || return 1
    windows_add_remove_programs_registered || return 1

    return 0
}

windows_prepare_uninstaller_copy()
{
    windows_paths

    mkdir -p "$WIN_SUPPORT_DIR" ||
        die "Could not create Windows uninstall support directory."

    ORIGINAL_IDENTITY="$INSTALLER_BASENAME"

    {
        printf '#!/usr/bin/env bash\n'
        printf 'export RZ27_INSTALLER_IDENTITY=%q\n' "$ORIGINAL_IDENTITY"
        printf 'export RZ27_INSTALL_DIR=%q\n' "$INSTALL_DIR"
        tail -n +2 "$INSTALLER_FILE"
    } > "$WIN_UNINSTALLER" ||
        die "Could not create Windows uninstall-program copy."

    chmod +x "$WIN_UNINSTALLER" 2>/dev/null || true
}

windows_register_add_remove_programs()
{
    windows_paths
    windows_prepare_uninstaller_copy

    UNINSTALL_KEY_PS="$(windows_escape_ps_single "$WIN_UNINSTALL_KEY")"
    DISPLAY_NAME_PS="$(windows_escape_ps_single "$INSTALLER_STEM")"
    INSTALL_DIR_PS="$(windows_escape_ps_single "$WIN_INSTALL_NATIVE")"
    UNINSTALLER_PS="$(windows_escape_ps_single "$WIN_UNINSTALLER_NATIVE")"
    BASH_PS="$(windows_escape_ps_single "$BASH_NATIVE")"

    UNINSTALL_STRING="\"$BASH_NATIVE\" \"$WIN_UNINSTALLER_NATIVE\" -u"
    UNINSTALL_STRING_PS="$(windows_escape_ps_single "$UNINSTALL_STRING")"

    PS_BODY="New-Item -Path '$UNINSTALL_KEY_PS' -Force | Out-Null; \
New-ItemProperty -Path '$UNINSTALL_KEY_PS' -Name DisplayName -Value '$DISPLAY_NAME_PS' -PropertyType String -Force | Out-Null; \
New-ItemProperty -Path '$UNINSTALL_KEY_PS' -Name DisplayVersion -Value '1.0' -PropertyType String -Force | Out-Null; \
New-ItemProperty -Path '$UNINSTALL_KEY_PS' -Name Publisher -Value 'RZ-27 Installer' -PropertyType String -Force | Out-Null; \
New-ItemProperty -Path '$UNINSTALL_KEY_PS' -Name InstallLocation -Value '$INSTALL_DIR_PS' -PropertyType String -Force | Out-Null; \
New-ItemProperty -Path '$UNINSTALL_KEY_PS' -Name UninstallString -Value '$UNINSTALL_STRING_PS' -PropertyType String -Force | Out-Null; \
New-ItemProperty -Path '$UNINSTALL_KEY_PS' -Name NoModify -Value 1 -PropertyType DWord -Force | Out-Null; \
New-ItemProperty -Path '$UNINSTALL_KEY_PS' -Name NoRepair -Value 1 -PropertyType DWord -Force | Out-Null"

    if [ -f "$WIN_ICON" ]; then
        ICON_NATIVE_PS="$(windows_escape_ps_single "$WIN_ICON_NATIVE")"
        PS_BODY="$PS_BODY; New-ItemProperty -Path '$UNINSTALL_KEY_PS' -Name DisplayIcon -Value '$ICON_NATIVE_PS' -PropertyType String -Force | Out-Null"
    fi

    PS_BODY_ESC="$(windows_escape_ps_single "$PS_BODY")"

    "$POWERSHELL_EXE" -NoProfile -ExecutionPolicy Bypass -Command \
        "Start-Process PowerShell -Verb RunAs -Wait -ArgumentList '-NoProfile','-ExecutionPolicy','Bypass','-Command','$PS_BODY_ESC'" \
        >/dev/null 2>&1 || return 1

    return 0
}

windows_unregister_add_remove_programs()
{
    windows_paths

    UNINSTALL_KEY_PS="$(windows_escape_ps_single "$WIN_UNINSTALL_KEY")"
    PS_BODY="Remove-Item -LiteralPath '$UNINSTALL_KEY_PS' -Recurse -Force -ErrorAction SilentlyContinue"
    PS_BODY_ESC="$(windows_escape_ps_single "$PS_BODY")"

    "$POWERSHELL_EXE" -NoProfile -ExecutionPolicy Bypass -Command \
        "Start-Process PowerShell -Verb RunAs -Wait -ArgumentList '-NoProfile','-ExecutionPolicy','Bypass','-Command','$PS_BODY_ESC'" \
        >/dev/null 2>&1 || true
}

windows_add_remove_programs_registered()
{
    windows_paths

    UNINSTALL_KEY_PS="$(windows_escape_ps_single "$WIN_UNINSTALL_KEY")"

    RESULT="$("$POWERSHELL_EXE" -NoProfile -Command \
        "if (Test-Path -LiteralPath '$UNINSTALL_KEY_PS') { 'yes' } else { 'no' }" \
        2>/dev/null | tr -d '\r')"

    [ "$RESULT" = "yes" ]
}

install_windows_launcher()
{
    windows_paths

    mkdir -p "$WIN_SUPPORT_DIR" || die "Could not create Windows launcher support directory."
    mkdir -p "$WIN_PROGRAMS_POSIX" 2>/dev/null || true

    generate_windows_runner > "$WIN_RUNNER" ||
        die "Could not create Windows launcher command file."

    if [ "$ICON_AVAILABLE" -eq 1 ]; then
        prepare_platform_icon ||
            die "Could not generate the Windows ICO icon."
    else
        rm -f "$WIN_ICON" 2>/dev/null || true
    fi

    SHORTCUT_PS="$(windows_escape_ps_single "$WIN_SHORTCUT_NATIVE")"
    RUNNER_PS="$(windows_escape_ps_single "$WIN_RUNNER_NATIVE")"
    INSTALL_PS="$(windows_escape_ps_single "$WIN_INSTALL_NATIVE")"

    if [ -f "$WIN_ICON" ]; then
        ICON_PS="$(windows_escape_ps_single "$WIN_ICON_NATIVE")"
    else
        ICON_PS=""
    fi

    PS_BODY="\$w=New-Object -ComObject WScript.Shell; \
\$s=\$w.CreateShortcut('$SHORTCUT_PS'); \
\$s.TargetPath='$RUNNER_PS'; \
\$s.WorkingDirectory='$INSTALL_PS'; \
\$s.Description='Launch $APP_NAME'; \
if ('$ICON_PS' -ne '') { \$s.IconLocation='$ICON_PS,0' }; \
\$s.Save()"

    PS_BODY_ESC="$(windows_escape_ps_single "$PS_BODY")"

    "$POWERSHELL_EXE" -NoProfile -ExecutionPolicy Bypass -Command \
        "Start-Process PowerShell -Verb RunAs -Wait -ArgumentList '-NoProfile','-ExecutionPolicy','Bypass','-Command','$PS_BODY_ESC'" ||
        die "Could not create Windows all-users Start Menu shortcut."

    windows_shortcut_registered ||
        die "Windows shortcut was created but could not be verified in the all-users Start Menu."

    windows_register_add_remove_programs ||
        die "Windows shortcut installed, but Add or Remove Programs registration failed."

    windows_add_remove_programs_registered ||
        die "Windows Add or Remove Programs registration could not be verified."

    write_state
    rz27_registry_add_current

    printf '\nInstalled/updated Windows launcher:\n  %s\n\n' "$WIN_SHORTCUT_NATIVE"
}

run_windows_start()
{
    windows_paths

    # UAC elevation is the Windows equivalent of the sudo boundary.
    # Launch an elevated cmd window, then run Start.sh through Bash.
    START_PS="$(windows_escape_ps_single "$WIN_START_NATIVE")"
    INSTALL_PS="$(windows_escape_ps_single "$WIN_INSTALL_NATIVE")"
    BASH_PS="$(windows_escape_ps_single "$BASH_NATIVE")"

    # Build a Bash command with POSIX paths, then pass it through cmd.exe.
    Q_INSTALL="$(printf "%s" "$INSTALL_DIR" | sed "s/'/'\\\\''/g")"
    Q_START="$(printf "%s" "$START_FILE" | sed "s/'/'\\\\''/g")"
    BASH_COMMAND="cd '$Q_INSTALL' && '$Q_START'; code=\$?; echo; echo Exit status: \$code; echo; read -r -p 'Press Enter to close...' _; exit \$code"

    CMD_NATIVE="$(windows_to_native "$(command -v cmd.exe 2>/dev/null || printf 'C:/Windows/System32/cmd.exe')")"

    # Escape embedded double quotes for the cmd /c string.
    BASH_COMMAND_CMD="$(printf '%s' "$BASH_COMMAND" | sed 's/"/\\"/g')"

    ARG_LINE="/k \"\"$BASH_NATIVE\" -lc \"$BASH_COMMAND_CMD\"\""

    ARG_PS="$(windows_escape_ps_single "$ARG_LINE")"
    CMD_PS="$(windows_escape_ps_single "$CMD_NATIVE")"

    "$POWERSHELL_EXE" -NoProfile -ExecutionPolicy Bypass -Command \
        "Start-Process -FilePath '$CMD_PS' -Verb RunAs -ArgumentList '$ARG_PS'" ||
        die "Windows elevation request failed."
}


# ============================================================
# INSTALLER MANAGER
# ============================================================

managed_install_count()
{
    COUNT=0

    [ -d "$LAUNCHER_ROOT" ] || {
        printf '0'
        return 0
    }

    for D in "$LAUNCHER_ROOT"/*; do
        [ -d "$D" ] || continue
        [ "$D" = "$MANAGER_STATE_DIR" ] && continue
        [ -f "$D/install.state" ] || continue
        COUNT=$((COUNT + 1))
    done

    printf '%s' "$COUNT"
}

list_managed_installs()
{
    INDEX=1

    [ -d "$LAUNCHER_ROOT" ] || return 0

    for D in "$LAUNCHER_ROOT"/*; do
        [ -d "$D" ] || continue
        [ "$D" = "$MANAGER_STATE_DIR" ] && continue
        [ -f "$D/install.state" ] || continue

        NAME="$(sed -n 's/^INSTALLER_NAME=//p' "$D/install.state" | head -n 1)"
        [ -n "$NAME" ] || NAME="$(basename "$D")"

        printf '%s) %s\n' "$INDEX" "$NAME"
        INDEX=$((INDEX + 1))
    done
}

managed_install_name_by_index()
{
    WANTED="$1"
    INDEX=1

    [ -d "$LAUNCHER_ROOT" ] || return 1

    for D in "$LAUNCHER_ROOT"/*; do
        [ -d "$D" ] || continue
        [ "$D" = "$MANAGER_STATE_DIR" ] && continue
        [ -f "$D/install.state" ] || continue

        if [ "$INDEX" -eq "$WANTED" ]; then
            NAME="$(sed -n 's/^INSTALLER_NAME=//p' "$D/install.state" | head -n 1)"
            [ -n "$NAME" ] || return 1
            printf '%s' "$NAME"
            return 0
        fi

        INDEX=$((INDEX + 1))
    done

    return 1
}

manager_linux_paths()
{
    MANAGER_LINUX_DESKTOP="/usr/share/applications/$MANAGER_ID.desktop"
    MANAGER_LINUX_WRAPPER="/usr/local/bin/$MANAGER_ID"
    MANAGER_LINUX_ICON="/usr/share/icons/hicolor/512x512/apps/$MANAGER_ID.png"
}

install_manager_linux()
{
    manager_linux_paths

    TMP_MANAGER_DIR="$(mktemp -d)" || die "Could not create Installer manager temporary directory."
    TMP_MANAGER_DESKTOP="$TMP_MANAGER_DIR/$MANAGER_ID.desktop"
    TMP_MANAGER_WRAPPER="$TMP_MANAGER_DIR/$MANAGER_ID"

    Q_DIR="$(printf "%s" "$INSTALL_DIR" | sed "s/'/'\\\\''/g")"
    Q_FILE="$(printf "%s" "$INSTALLER_FILE" | sed "s/'/'\\\\''/g")"

    cat > "$TMP_MANAGER_WRAPPER" <<EOF
#!/usr/bin/env bash
cd '$Q_DIR' || exit 1
exec '$Q_FILE' --manager
EOF

    cat > "$TMP_MANAGER_DESKTOP" <<EOF
[Desktop Entry]
Version=1.0
Type=Application
Name=$MANAGER_NAME
Comment=Install or remove managed script applications
Exec=$MANAGER_LINUX_WRAPPER
TryExec=$MANAGER_LINUX_WRAPPER
Terminal=true
StartupNotify=true
Icon=$MANAGER_ID
Categories=Utility;
EOF

    chmod +x "$TMP_MANAGER_WRAPPER"

    if command -v desktop-file-validate >/dev/null 2>&1; then
        desktop-file-validate "$TMP_MANAGER_DESKTOP" ||
            die "Installer manager desktop entry failed validation."
    fi

    run_linux_elevated install -m 0755 "$TMP_MANAGER_WRAPPER" "$MANAGER_LINUX_WRAPPER" ||
        die "Could not install Installer manager command."

    run_linux_elevated install -m 0644 "$TMP_MANAGER_DESKTOP" "$MANAGER_LINUX_DESKTOP" ||
        die "Could not install Installer manager desktop entry."

    if [ -f "$ICON_FILE" ]; then
        run_linux_elevated mkdir -p "$(dirname "$MANAGER_LINUX_ICON")" || true
        run_linux_elevated install -m 0644 "$ICON_FILE" "$MANAGER_LINUX_ICON" || true
    fi

    rm -rf "$TMP_MANAGER_DIR"

    command -v update-desktop-database >/dev/null 2>&1 &&
        run_linux_elevated update-desktop-database /usr/share/applications >/dev/null 2>&1 || true

    command -v gtk-update-icon-cache >/dev/null 2>&1 &&
        run_linux_elevated gtk-update-icon-cache -f -t /usr/share/icons/hicolor >/dev/null 2>&1 || true

    refresh_pantheon_applications_menu
}

install_manager_macos()
{
    MANAGER_MAC_APP="/Applications/$MANAGER_NAME.app"
    TMP_MANAGER_ROOT="$(mktemp -d)" || die "Could not create Installer manager bundle."
    TMP_MANAGER_APP="$TMP_MANAGER_ROOT/$MANAGER_NAME.app"

    mkdir -p "$TMP_MANAGER_APP/Contents/MacOS" "$TMP_MANAGER_APP/Contents/Resources" ||
        die "Could not create Installer manager bundle."

    Q_DIR="$(mac_shell_quote "$INSTALL_DIR")"
    Q_FILE="$(mac_shell_quote "$INSTALLER_FILE")"

    cat > "$TMP_MANAGER_APP/Contents/MacOS/launcher" <<EOF
#!/usr/bin/env bash
COMMAND="cd $Q_DIR && $Q_FILE --manager"
osascript - "\$COMMAND" <<'APPLESCRIPT'
on run argv
    set shellCommand to item 1 of argv
    tell application "Terminal"
        activate
        do script shellCommand
    end tell
end run
APPLESCRIPT
EOF
    chmod +x "$TMP_MANAGER_APP/Contents/MacOS/launcher"

    cat > "$TMP_MANAGER_APP/Contents/Info.plist" <<EOF
<?xml version="1.0" encoding="UTF-8"?>
<!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN"
  "http://www.apple.com/DTDs/PropertyList-1.0.dtd">
<plist version="1.0">
<dict>
    <key>CFBundleName</key><string>$MANAGER_NAME</string>
    <key>CFBundleDisplayName</key><string>$MANAGER_NAME</string>
    <key>CFBundleExecutable</key><string>launcher</string>
    <key>CFBundleIdentifier</key><string>local.rz27.installer.manager</string>
    <key>CFBundlePackageType</key><string>APPL</string>
    <key>LSApplicationCategoryType</key><string>public.app-category.utilities</string>
    <key>CFBundleIconFile</key><string>icon.icns</string>
</dict>
</plist>
EOF

    if [ -f "$ICON_FILE" ]; then
        OLD_MAC_APP_DIR="${MAC_APP_DIR:-}"
        OLD_MAC_CONTENTS="${MAC_CONTENTS:-}"
        OLD_MAC_MACOS="${MAC_MACOS:-}"
        OLD_MAC_RESOURCES="${MAC_RESOURCES:-}"
        OLD_MAC_ICON="${MAC_ICON:-}"

        MAC_APP_DIR="$TMP_MANAGER_APP"
        MAC_CONTENTS="$TMP_MANAGER_APP/Contents"
        MAC_MACOS="$TMP_MANAGER_APP/Contents/MacOS"
        MAC_RESOURCES="$TMP_MANAGER_APP/Contents/Resources"
        MAC_ICON="$TMP_MANAGER_APP/Contents/Resources/icon.icns"
        mac_make_icns || true

        MAC_APP_DIR="$OLD_MAC_APP_DIR"
        MAC_CONTENTS="$OLD_MAC_CONTENTS"
        MAC_MACOS="$OLD_MAC_MACOS"
        MAC_RESOURCES="$OLD_MAC_RESOURCES"
        MAC_ICON="$OLD_MAC_ICON"
    fi

    run_mac_elevated rm -rf "$MANAGER_MAC_APP" || true
    run_mac_elevated cp -R "$TMP_MANAGER_APP" "$MANAGER_MAC_APP" ||
        die "Could not install Installer manager into /Applications."

    rm -rf "$TMP_MANAGER_ROOT"

    LSREGISTER="/System/Library/Frameworks/CoreServices.framework/Frameworks/LaunchServices.framework/Support/lsregister"
    [ -x "$LSREGISTER" ] && "$LSREGISTER" -f "$MANAGER_MAC_APP" >/dev/null 2>&1 || true
}

install_manager_windows()
{
    windows_find_powershell
    windows_find_bash

    MANAGER_WIN_DIR="$MANAGER_STATE_DIR"
    MANAGER_WIN_RUNNER="$MANAGER_WIN_DIR/Installer-manager.cmd"
    MANAGER_WIN_ICON="$MANAGER_WIN_DIR/Installer.ico"

    mkdir -p "$MANAGER_WIN_DIR" || die "Could not create Installer manager support directory."

    INSTALL_NATIVE="$(windows_to_native "$INSTALL_DIR")"
    FILE_NATIVE="$(windows_to_native "$INSTALLER_FILE")"

    cat > "$MANAGER_WIN_RUNNER" <<EOF
@echo off
cd /d "$INSTALL_NATIVE"
"$BASH_NATIVE" "$FILE_NATIVE" --manager
EOF

    if [ -f "$ICON_FILE" ]; then
        OLD_STATE_DIR="$STATE_DIR"
        OLD_WIN_SUPPORT_DIR="${WIN_SUPPORT_DIR:-}"
        OLD_WIN_ICON="${WIN_ICON:-}"
        STATE_DIR="$MANAGER_STATE_DIR"
        WIN_SUPPORT_DIR="$MANAGER_STATE_DIR"
        WIN_ICON="$MANAGER_WIN_ICON"
        windows_make_icon || true
        STATE_DIR="$OLD_STATE_DIR"
        WIN_SUPPORT_DIR="$OLD_WIN_SUPPORT_DIR"
        WIN_ICON="$OLD_WIN_ICON"
    fi

    COMMON_PROGRAMS="$("$POWERSHELL_EXE" -NoProfile -Command "[Environment]::GetFolderPath('CommonPrograms')" 2>/dev/null | tr -d '\r')"
    MANAGER_SHORTCUT="$COMMON_PROGRAMS\\Installer.lnk"
    RUNNER_NATIVE="$(windows_to_native "$MANAGER_WIN_RUNNER")"
    ICON_NATIVE="$(windows_to_native "$MANAGER_WIN_ICON")"

    SC_PS="$(windows_escape_ps_single "$MANAGER_SHORTCUT")"
    RUN_PS="$(windows_escape_ps_single "$RUNNER_NATIVE")"
    WD_PS="$(windows_escape_ps_single "$INSTALL_NATIVE")"
    ICO_PS="$(windows_escape_ps_single "$ICON_NATIVE")"

    BODY="\$w=New-Object -ComObject WScript.Shell; \$s=\$w.CreateShortcut('$SC_PS'); \$s.TargetPath='$RUN_PS'; \$s.WorkingDirectory='$WD_PS'; \$s.Description='Install or remove managed script applications'; if (Test-Path '$ICO_PS') { \$s.IconLocation='$ICO_PS,0' }; \$s.Save()"
    BODY_ESC="$(windows_escape_ps_single "$BODY")"

    "$POWERSHELL_EXE" -NoProfile -ExecutionPolicy Bypass -Command \
        "Start-Process PowerShell -Verb RunAs -Wait -ArgumentList '-NoProfile','-ExecutionPolicy','Bypass','-Command','$BODY_ESC'" ||
        die "Could not install Windows Installer manager shortcut."
}

manager_is_installed()
{
    case "$PLATFORM" in
        linux)
            manager_linux_paths
            [ -f "$MANAGER_LINUX_DESKTOP" ] && [ -x "$MANAGER_LINUX_WRAPPER" ]
            ;;
        macos)
            [ -d "/Applications/$MANAGER_NAME.app" ]
            ;;
        windows)
            windows_find_powershell
            COMMON_PROGRAMS="$("$POWERSHELL_EXE" -NoProfile -Command "[Environment]::GetFolderPath('CommonPrograms')" 2>/dev/null | tr -d '\r')"
            [ -n "$COMMON_PROGRAMS" ] || return 1
            if command -v cygpath >/dev/null 2>&1; then
                [ -f "$(cygpath -u "$COMMON_PROGRAMS")/Installer.lnk" ]
            else
                return 1
            fi
            ;;
    esac
}

ensure_installer_manager()
{
    rz27_ensure_registry
    manager_is_installed && return 0

    mkdir -p "$MANAGER_STATE_DIR" || die "Could not create Installer manager state."

    case "$PLATFORM" in
        linux) install_manager_linux ;;
        macos) install_manager_macos ;;
        windows) install_manager_windows ;;
    esac

    {
        printf 'MANAGER=1\n'
        printf 'INSTALL_DIR=%s\n' "$INSTALL_DIR"
        printf 'INSTALLER_FILE=%s\n' "$INSTALLER_FILE"
    } > "$MANAGER_STATE_FILE"

    printf '\nDedicated Installer application installed.\n'
}

repair_installer_manager()
{
    # Preserve the transparent install registry across repair/update passes.
    rz27_registry_paths

    SAVED_LOG=""
    if [ -f "$RZ27_INSTALL_LOG" ]; then
        SAVED_LOG="$(mktemp)" || die "Could not preserve install registry during repair."
        cp -f "$RZ27_INSTALL_LOG" "$SAVED_LOG" ||
            die "Could not preserve install registry during repair."
    fi

    # Remove only Installer-manager integration/support artifacts.
    # Managed child launchers/states are intentionally untouched.
    case "$PLATFORM" in
        linux)
            manager_linux_paths
            run_linux_elevated rm -f \
                "$MANAGER_LINUX_DESKTOP" \
                "$MANAGER_LINUX_WRAPPER" \
                "$MANAGER_LINUX_ICON" >/dev/null 2>&1 || true

            command -v update-desktop-database >/dev/null 2>&1 &&
                run_linux_elevated update-desktop-database /usr/share/applications >/dev/null 2>&1 || true
            ;;
        macos)
            MANAGER_MAC_APP="/Applications/$MANAGER_NAME.app"
            LSREGISTER="/System/Library/Frameworks/CoreServices.framework/Frameworks/LaunchServices.framework/Support/lsregister"

            if [ -x "$LSREGISTER" ] && [ -d "$MANAGER_MAC_APP" ]; then
                "$LSREGISTER" -u "$MANAGER_MAC_APP" >/dev/null 2>&1 || true
            fi

            run_mac_elevated rm -rf "$MANAGER_MAC_APP" >/dev/null 2>&1 || true
            ;;
        windows)
            windows_find_powershell
            COMMON_PROGRAMS="$("$POWERSHELL_EXE" -NoProfile -Command \
                "[Environment]::GetFolderPath('CommonPrograms')" 2>/dev/null | tr -d '\r')"

            if [ -n "$COMMON_PROGRAMS" ]; then
                MANAGER_SHORTCUT="$COMMON_PROGRAMS\\Installer.lnk"
                SC_PS="$(windows_escape_ps_single "$MANAGER_SHORTCUT")"
                "$POWERSHELL_EXE" -NoProfile -ExecutionPolicy Bypass -Command \
                    "Start-Process PowerShell -Verb RunAs -Wait -ArgumentList '-NoProfile','-Command','Remove-Item -LiteralPath ''$SC_PS'' -Force -ErrorAction SilentlyContinue'" \
                    >/dev/null 2>&1 || true
            fi
            ;;
    esac

    rm -rf "$MANAGER_STATE_DIR" 2>/dev/null || true

    # Restore the embedded default Installer artwork unconditionally so an
    # updated Installer carries its current icon/resources.
    mkdir -p "$(dirname "$ICON_FILE")" 2>/dev/null || true
    decode_base64_stream_to_file "$ICON_FILE" ||
        die "Could not restore embedded Installer icon during repair."

    ICON_AVAILABLE=1

    # Reinstall current manager launcher/support files from this script version.
    ensure_installer_manager

    # Restore the previous install registry exactly if one existed.
    if [ -n "$SAVED_LOG" ] && [ -f "$SAVED_LOG" ]; then
        mkdir -p "$RZ27_RECORD_DIR" ||
            die "Could not recreate RZ-27 records directory."
        cp -f "$SAVED_LOG" "$RZ27_INSTALL_LOG" ||
            die "Could not restore install registry after repair."
        rm -f "$SAVED_LOG" 2>/dev/null || true
    fi
}

remove_installer_manager()
{
    case "$PLATFORM" in
        linux)
            manager_linux_paths
            run_linux_elevated rm -f "$MANAGER_LINUX_DESKTOP" "$MANAGER_LINUX_WRAPPER" "$MANAGER_LINUX_ICON" >/dev/null 2>&1 || true
            command -v update-desktop-database >/dev/null 2>&1 &&
                run_linux_elevated update-desktop-database /usr/share/applications >/dev/null 2>&1 || true
            refresh_pantheon_applications_menu
            ;;
        macos)
            MANAGER_MAC_APP="/Applications/$MANAGER_NAME.app"
            LSREGISTER="/System/Library/Frameworks/CoreServices.framework/Frameworks/LaunchServices.framework/Support/lsregister"
            [ -x "$LSREGISTER" ] && [ -d "$MANAGER_MAC_APP" ] &&
                "$LSREGISTER" -u "$MANAGER_MAC_APP" >/dev/null 2>&1 || true
            run_mac_elevated rm -rf "$MANAGER_MAC_APP" >/dev/null 2>&1 || true
            ;;
        windows)
            windows_find_powershell
            COMMON_PROGRAMS="$("$POWERSHELL_EXE" -NoProfile -Command "[Environment]::GetFolderPath('CommonPrograms')" 2>/dev/null | tr -d '\r')"
            MANAGER_SHORTCUT="$COMMON_PROGRAMS\\Installer.lnk"
            SC_PS="$(windows_escape_ps_single "$MANAGER_SHORTCUT")"
            "$POWERSHELL_EXE" -NoProfile -ExecutionPolicy Bypass -Command \
                "Start-Process PowerShell -Verb RunAs -Wait -ArgumentList '-NoProfile','-Command','Remove-Item -LiteralPath ''$SC_PS'' -Force -ErrorAction SilentlyContinue'" \
                >/dev/null 2>&1 || true
            ;;
    esac

    rm -rf "$MANAGER_STATE_DIR" 2>/dev/null || true
    rmdir "$LAUNCHER_ROOT" 2>/dev/null || true
}

open_installed_script_in_editor()
{
    EDIT_FILE="$1"

    [ -f "$EDIT_FILE" ] || {
        printf '\nEditor was not opened because the script file does not exist:\n'
        printf '  %s\n' "$EDIT_FILE"
        return 0
    }

    case "$PLATFORM" in
        linux)
            if command -v xdg-open >/dev/null 2>&1; then
                xdg-open "$EDIT_FILE" >/dev/null 2>&1 &
            elif command -v gio >/dev/null 2>&1; then
                gio open "$EDIT_FILE" >/dev/null 2>&1 &
            else
                printf '\nNo default desktop opener was found.\n'
            fi
            ;;
        macos)
            if command -v open >/dev/null 2>&1; then
                # -t asks macOS to open the file in the user's text editor.
                open -t "$EDIT_FILE" >/dev/null 2>&1 &
            fi
            ;;
        windows)
            windows_find_powershell
            EDIT_NATIVE="$(windows_to_native "$EDIT_FILE")"
            EDIT_PS="$(windows_escape_ps_single "$EDIT_NATIVE")"
            "$POWERSHELL_EXE" -NoProfile -Command \
                "Start-Process -FilePath '$EDIT_PS'" >/dev/null 2>&1 &
            ;;
    esac
}

offer_editor_after_install()
{
    EDIT_FILE="$1"
    EDIT_WORKDIR="$2"

    printf '\nPost-install action:\n'
    printf '  y = open installed script in the default text editor\n'
    printf '  n = do not open\n'
    printf '  c = enter a custom launch command instead\n'
    printf '  blank = exit without opening\n'
    printf '> '

    IFS= read -r EDIT_CHOICE || EDIT_CHOICE=""

    case "$EDIT_CHOICE" in
        y|Y|yes|YES|Yes)
            open_installed_script_in_editor "$EDIT_FILE"
            ;;
        c|C)
            printf '\nCustom launch command\n'
            printf 'Working directory:\n  %s\n' "$EDIT_WORKDIR"
            printf 'Example: python %s -say\n' "$(basename "$EDIT_FILE")"
            printf 'Command: '
            IFS= read -r POST_INSTALL_COMMAND || POST_INSTALL_COMMAND=""
            [ -n "$POST_INSTALL_COMMAND" ] || {
                printf 'No command entered; leaving launcher unchanged.\n'
                return 0
            }

            # Persist the command into the child metadata and Start.sh so this
            # becomes the audited installed launch command rather than merely
            # a one-session editor action.
            if [ -n "${LAST_CHILD_IDENTITY:-}" ]; then
                RZ27_INSTALLER_IDENTITY="$LAST_CHILD_IDENTITY" \
                RZ27_INSTALL_DIR="$INSTALL_DIR" \
                RZ27_MANAGER_CHILD=1 \
                RZ27_FORCE_RECONFIGURE=1 \
                RZ27_SELECTED_LAUNCH_TARGET="$EDIT_FILE" \
                RZ27_CUSTOM_LAUNCH_COMMAND="$POST_INSTALL_COMMAND" \
                RZ27_CUSTOM_APP_NAME="${LAST_CHILD_APP_NAME:-$(basename "$EDIT_FILE")}" \
                RZ27_CUSTOM_ICON_FILE="${LAST_CHILD_ICON:-}" \
                RZ27_CUSTOM_WORKDIR="$EDIT_WORKDIR" \
                RZ27_SOURCE_SCRIPT="${LAST_CHILD_SOURCE:-$EDIT_FILE}" \
                    "$INSTALLER_FILE"
            fi
            ;;
        n|N|no|NO|No|'')
            return 0
            ;;
        *)
            printf 'Unrecognized choice; exiting without opening the editor.\n'
            ;;
    esac
}

create_manual_script_template()
{
    MANUAL_DIR="$1"

    if [ "$PLATFORM" = "windows" ]; then
        MANUAL_FILE="$MANUAL_DIR/unnamed.cmd"
        cat > "$MANUAL_FILE" <<'EOF'
@echo off
echo blank world
echo.
pause
EOF
    else
        MANUAL_FILE="$MANUAL_DIR/unnamed.sh"
        cat > "$MANUAL_FILE" <<'EOF'
#!/bin/bash
EOF
        chmod +x "$MANUAL_FILE" 2>/dev/null || true
    fi

    printf '%s' "$MANUAL_FILE"
}

create_blank_icon_template()
{
    ICON_TEMPLATE="$1"

    # A valid 1x1 transparent PNG gives the user a harmless placeholder they
    # can replace later without borrowing the Installer's branded icon.
    TRANSPARENT_PNG_B64='iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVQIHWP4z8DwHwAFgAI/ScL8WQAAAABJRU5ErkJggg=='

    if command -v base64 >/dev/null 2>&1; then
        printf '%s' "$TRANSPARENT_PNG_B64" | base64 --decode > "$ICON_TEMPLATE" 2>/dev/null ||
        printf '%s' "$TRANSPARENT_PNG_B64" | base64 -D > "$ICON_TEMPLATE" 2>/dev/null ||
        return 1
    else
        return 1
    fi
}

make_child_runnable()
{
    RUN_FILE="$1"

    case "$PLATFORM" in
        linux|macos)
            chmod +x "$RUN_FILE" 2>/dev/null || true
            ;;
        windows)
            # .cmd/.bat files are natively executable by Windows. For shell
            # scripts in a Bash environment, keep the executable bit as well.
            chmod +x "$RUN_FILE" 2>/dev/null || true
            ;;
    esac
}

create_local_start_launcher()
{
    PAYLOAD_FILE="$1"
    WORK_DIR="$2"
    CUSTOM_COMMAND="$3"

    LOCAL_START="$WORK_DIR/Start.sh"

    # If the payload itself is Start.sh, it already is the local handoff file.
    # Do not overwrite it with a wrapper around itself.
    if [ "$PAYLOAD_FILE" = "$LOCAL_START" ]; then
        make_child_runnable "$LOCAL_START"
        printf '%s' "$LOCAL_START"
        return 0
    fi

    PAYLOAD_NAME="$(basename "$PAYLOAD_FILE")"
    PAYLOAD_Q="$(printf '%q' "$PAYLOAD_NAME")"
    WORKDIR_Q="$(printf '%q' "$WORK_DIR")"

    if [ -n "$CUSTOM_COMMAND" ]; then
        COMMAND_Q="$(printf '%q' "$CUSTOM_COMMAND")"

        cat > "$LOCAL_START" <<EOF
#!/usr/bin/env bash

# RZ-27 local application handoff.
# This file intentionally lives beside the application payload.
# Working directory:
#   $WORK_DIR

APP_DIRECTORY=$WORKDIR_Q
LAUNCH_COMMAND=$COMMAND_Q

cd "\$APP_DIRECTORY" || exit 1

while :; do
    bash -lc "\$LAUNCH_COMMAND"
    LAUNCH_STATUS=\$?

    [ "\$LAUNCH_STATUS" -eq 0 ] && exit 0

    echo
    echo "LAUNCH FAILED"
    echo
    echo "The command used was:"
    echo "  \$LAUNCH_COMMAND"
    echo
    echo "Exit status: \$LAUNCH_STATUS"
    echo
    echo "Input a revised command to continue."
    echo "Leave blank to retry the same command."
    echo "Press q to exit."
    echo
    printf '> '

    IFS= read -r REVISED_COMMAND || exit "\$LAUNCH_STATUS"

    case "\$REVISED_COMMAND" in
        q|Q) exit "\$LAUNCH_STATUS" ;;
        '') ;;
        *) LAUNCH_COMMAND="\$REVISED_COMMAND" ;;
    esac
done
EOF
    else
        case "$PAYLOAD_FILE" in
            *.cmd|*.CMD|*.bat|*.BAT)
                cat > "$LOCAL_START" <<EOF
#!/usr/bin/env bash

# RZ-27 local application handoff.
# Payload:
#   $PAYLOAD_NAME

APP_DIRECTORY=$WORKDIR_Q
PAYLOAD_NAME=$PAYLOAD_Q
LAUNCH_COMMAND="cmd.exe /c \"\$PAYLOAD_NAME\""

cd "\$APP_DIRECTORY" || exit 1

while :; do
    bash -lc "\$LAUNCH_COMMAND"
    LAUNCH_STATUS=\$?

    [ "\$LAUNCH_STATUS" -eq 0 ] && exit 0

    echo
    echo "LAUNCH FAILED"
    echo
    echo "The command used was:"
    echo "  \$LAUNCH_COMMAND"
    echo
    echo "Exit status: \$LAUNCH_STATUS"
    echo
    echo "Input a revised command to continue."
    echo "Leave blank to retry the same command."
    echo "Press q to exit."
    echo
    printf '> '

    IFS= read -r REVISED_COMMAND || exit "\$LAUNCH_STATUS"

    case "\$REVISED_COMMAND" in
        q|Q) exit "\$LAUNCH_STATUS" ;;
        '') ;;
        *) LAUNCH_COMMAND="\$REVISED_COMMAND" ;;
    esac
done
EOF
                ;;
            *)
                cat > "$LOCAL_START" <<EOF
#!/usr/bin/env bash

# RZ-27 local application handoff.
# Payload:
#   $PAYLOAD_NAME
#
# Start.sh and the payload are intentionally kept together.

APP_DIRECTORY=$WORKDIR_Q
PAYLOAD_NAME=$PAYLOAD_Q
LAUNCH_COMMAND="./\$PAYLOAD_NAME"

cd "\$APP_DIRECTORY" || exit 1

while :; do
    if [ ! -e "\$PAYLOAD_NAME" ]; then
        LAUNCH_STATUS=127
    else
        bash -lc "\$LAUNCH_COMMAND"
        LAUNCH_STATUS=\$?
    fi

    [ "\$LAUNCH_STATUS" -eq 0 ] && exit 0

    echo
    echo "LAUNCH FAILED"
    echo
    echo "The command used was:"
    echo "  \$LAUNCH_COMMAND"
    echo
    echo "Exit status: \$LAUNCH_STATUS"
    echo
    echo "Input a revised command to continue."
    echo "Leave blank to retry the same command."
    echo "Press q to exit."
    echo
    printf '> '

    IFS= read -r REVISED_COMMAND || exit "\$LAUNCH_STATUS"

    case "\$REVISED_COMMAND" in
        q|Q) exit "\$LAUNCH_STATUS" ;;
        '') ;;
        *) LAUNCH_COMMAND="\$REVISED_COMMAND" ;;
    esac
done
EOF
                ;;
        esac
    fi

    make_child_runnable "$LOCAL_START"
    printf '%s' "$LOCAL_START"
}

manager_install_child()
{

    printf '\n'
    printf '============================================================\n'
    printf ' New managed application\n'
    printf '============================================================\n'
    printf '\n'
    printf 'Enter a script/executable path, or choose:\n'
    printf '  q = return to Installer Manager\n'
    printf '  blank = use the default template\n'
    printf '  t = use the default template\n'
    printf '  d = choose an application directory/template destination\n'
    printf '\n'
    printf 'Selection or script path: '

    IFS= read -r NEW_APP_INPUT || return 0

    CHILD_CUSTOM_WORKDIR=""
    CHILD_SOURCE_SCRIPT=""
    CHILD_TEMPLATE_MODE=0
    CHILD_MANUAL_MODE=0
    CHILD_COPIED=0

    case "$NEW_APP_INPUT" in
        q|Q)
            printf '\nReturning to Installer Manager.\n'
            return 0
            ;;

        ''|t|T)
            # Default template lives in this install identity's state until
            # the user optionally chooses another path through d.
            CHILD_TEMPLATE_MODE=1
            CHILD_SCRIPT_DIR="$INSTALL_DIR"
            if [ "$PLATFORM" = "windows" ]; then
                CHILD_FILE_NAME="Start.cmd"
                CHILD_TARGET="$CHILD_SCRIPT_DIR/$CHILD_FILE_NAME"
                cat > "$CHILD_TARGET" <<'EOF'
@echo off
echo blank world
echo.
pause
EOF
            else
                CHILD_FILE_NAME="Start.sh"
                CHILD_TARGET="$CHILD_SCRIPT_DIR/$CHILD_FILE_NAME"
                cat > "$CHILD_TARGET" <<'EOF'
#!/bin/bash
echo "blank world"
printf "Press Enter to exit..."
read -r _
EOF
            fi
            make_child_runnable "$CHILD_TARGET"
            CHILD_SOURCE_SCRIPT="default-template"
            CHILD_DEFAULT_NAME="${CHILD_FILE_NAME%.*}"
            ;;

        d|D)
            printf '\nApplication directory\n'
            printf 'Enter the directory to install/run this application from.\n'
            printf '  blank = installer directory:\n'
            printf '          %s\n' "$INSTALL_DIR"
            printf '  b     = template directory:\n'
            printf '          %s/.templates\n' "$INSTALL_DIR"
            printf 'Path: '
            IFS= read -r RAW_APP_DIR || RAW_APP_DIR=""

            case "$RAW_APP_DIR" in
                '')
                    CHILD_SCRIPT_DIR="$INSTALL_DIR"
                    ;;
                b|B)
                    CHILD_SCRIPT_DIR="$INSTALL_DIR/.templates"
                    ;;
                *)
                    CHILD_SCRIPT_DIR="$(normalize_launch_target "$RAW_APP_DIR")"
                    ;;
            esac

            mkdir -p "$CHILD_SCRIPT_DIR" ||
                die "Could not create application directory: $CHILD_SCRIPT_DIR"

            CHILD_SCRIPT_DIR="$(cd "$CHILD_SCRIPT_DIR" 2>/dev/null && pwd -P)"
            [ -n "$CHILD_SCRIPT_DIR" ] || die "Could not resolve application directory."
            CHILD_CUSTOM_WORKDIR="$CHILD_SCRIPT_DIR"

            printf '\nScript/template name\n'
            if [ "$PLATFORM" = "windows" ]; then
                printf '  blank = Start.cmd\n'
            else
                printf '  blank = Start.sh\n'
            fi
            printf '  M     = manual blank template (unnamed.%s)\n' "$([ "$PLATFORM" = "windows" ] && printf 'cmd' || printf 'sh')"
            printf '  path  = copy that existing script into the application directory\n'
            printf '  name  = create the default template with that filename\n'
            printf 'Entry: '
            IFS= read -r SCRIPT_ENTRY || SCRIPT_ENTRY=""

            case "$SCRIPT_ENTRY" in
                M|m)
                    CHILD_MANUAL_MODE=1
                    CHILD_TARGET="$(create_manual_script_template "$CHILD_SCRIPT_DIR")" ||
                        die "Could not create manual script template."
                    CHILD_FILE_NAME="$(basename "$CHILD_TARGET")"
                    CHILD_SOURCE_SCRIPT="manual-template"
                    ;;
                '')
                    if [ "$PLATFORM" = "windows" ]; then
                        CHILD_FILE_NAME="Start.cmd"
                        CHILD_TARGET="$CHILD_SCRIPT_DIR/$CHILD_FILE_NAME"
                        cat > "$CHILD_TARGET" <<'EOF'
@echo off
echo blank world
echo.
pause
EOF
                    else
                        CHILD_FILE_NAME="Start.sh"
                        CHILD_TARGET="$CHILD_SCRIPT_DIR/$CHILD_FILE_NAME"
                        cat > "$CHILD_TARGET" <<'EOF'
#!/bin/bash
echo "blank world"
printf "Press Enter to exit..."
read -r _
EOF
                    fi
                    CHILD_SOURCE_SCRIPT="default-template"
                    CHILD_TEMPLATE_MODE=1
                    ;;
                *)
                    POSSIBLE_SOURCE="$(normalize_launch_target "$SCRIPT_ENTRY")"
                    if [ -f "$POSSIBLE_SOURCE" ]; then
                        CHILD_SOURCE_SCRIPT="$POSSIBLE_SOURCE"
                        CHILD_FILE_NAME="$(basename "$POSSIBLE_SOURCE")"
                        CHILD_TARGET="$CHILD_SCRIPT_DIR/$CHILD_FILE_NAME"
                        cp -f "$POSSIBLE_SOURCE" "$CHILD_TARGET" ||
                            die "Could not copy script into application directory."
                        CHILD_COPIED=1
                    else
                        CHILD_FILE_NAME="$(basename "$SCRIPT_ENTRY")"
                        case "$CHILD_FILE_NAME" in
                            *.*) ;;
                            *)
                                if [ "$PLATFORM" = "windows" ]; then
                                    CHILD_FILE_NAME="$CHILD_FILE_NAME.cmd"
                                else
                                    CHILD_FILE_NAME="$CHILD_FILE_NAME.sh"
                                fi
                                ;;
                        esac
                        CHILD_TARGET="$CHILD_SCRIPT_DIR/$CHILD_FILE_NAME"
                        if [ "$PLATFORM" = "windows" ]; then
                            cat > "$CHILD_TARGET" <<'EOF'
@echo off
echo blank world
echo.
pause
EOF
                        else
                            cat > "$CHILD_TARGET" <<'EOF'
#!/bin/bash
echo "blank world"
printf "Press Enter to exit..."
read -r _
EOF
                        fi
                        CHILD_SOURCE_SCRIPT="named-default-template"
                        CHILD_TEMPLATE_MODE=1
                    fi
                    ;;
            esac

            make_child_runnable "$CHILD_TARGET"
            CHILD_DEFAULT_NAME="${CHILD_FILE_NAME%.*}"
            [ -n "$CHILD_DEFAULT_NAME" ] || CHILD_DEFAULT_NAME="$CHILD_FILE_NAME"
            ;;

        *)
            CHILD_SOURCE_SCRIPT="$(normalize_launch_target "$NEW_APP_INPUT")"

            if [ ! -f "$CHILD_SOURCE_SCRIPT" ]; then
                printf '\nThe selected script/executable does not exist:\n'
                printf '  %s\n\n' "$NEW_APP_INPUT"
                return 0
            fi

            CHILD_SCRIPT_DIR="$(cd "$(dirname "$CHILD_SOURCE_SCRIPT")" 2>/dev/null && pwd -P)"
            [ -n "$CHILD_SCRIPT_DIR" ] || CHILD_SCRIPT_DIR="$(dirname "$CHILD_SOURCE_SCRIPT")"
            CHILD_FILE_NAME="$(basename "$CHILD_SOURCE_SCRIPT")"
            CHILD_TARGET="$CHILD_SOURCE_SCRIPT"
            CHILD_DEFAULT_NAME="${CHILD_FILE_NAME%.*}"
            [ -n "$CHILD_DEFAULT_NAME" ] || CHILD_DEFAULT_NAME="$CHILD_FILE_NAME"
            make_child_runnable "$CHILD_TARGET"
            ;;
    esac

    CHILD_DEFAULT_ICON="$CHILD_SCRIPT_DIR/icon.png"
    CHILD_LAUNCH_COMMAND=""

    if [ "$CHILD_TEMPLATE_MODE" -eq 0 ] && [ "$CHILD_MANUAL_MODE" -eq 0 ]; then
        case "$CHILD_TARGET" in
            *.sh|*.SH|*.cmd|*.CMD|*.bat|*.BAT)
                ;;
            *)
                printf '\nThe selected target is not a directly recognized shell launcher.\n'
                printf 'Custom launch command [blank or d = execute selected file directly]: '
                IFS= read -r CHILD_LAUNCH_COMMAND || CHILD_LAUNCH_COMMAND=""
                case "$CHILD_LAUNCH_COMMAND" in d|D) CHILD_LAUNCH_COMMAND="" ;; esac
                ;;
        esac
    fi

    # Every managed application gets a local Start.sh in its application
    # directory. The OS launcher points to this handoff, which in turn launches
    # the neighboring payload script/command.
    CHILD_PAYLOAD_TARGET="$CHILD_TARGET"
    CHILD_LOCAL_START="$(create_local_start_launcher "$CHILD_PAYLOAD_TARGET" "$CHILD_SCRIPT_DIR" "$CHILD_LAUNCH_COMMAND")" ||
        die "Could not create local Start.sh launcher."

    printf '\nCreated local launcher:\n'
    printf '  %s\n' "$CHILD_LOCAL_START"
    if [ "$CHILD_PAYLOAD_TARGET" != "$CHILD_LOCAL_START" ]; then
        printf 'Payload beside it:\n'
        printf '  %s\n' "$CHILD_PAYLOAD_TARGET"
    fi

    printf '\nDefaults for this application:\n'
    printf '  Application dir : %s\n' "$CHILD_SCRIPT_DIR"
    printf '  Script          : %s\n' "$CHILD_TARGET"
    printf '  Default app name: %s\n' "$CHILD_DEFAULT_NAME"
    printf '  Default icon    : %s\n' "$CHILD_DEFAULT_ICON"
    printf '\n'

    printf 'Application name [default: %s] (blank or d = default): ' "$CHILD_DEFAULT_NAME"
    IFS= read -r CHILD_CUSTOM_NAME || CHILD_CUSTOM_NAME=""
    case "$CHILD_CUSTOM_NAME" in
        ''|d|D) CHILD_CUSTOM_NAME="$CHILD_DEFAULT_NAME" ;;
    esac

    printf '\nIcon selection:\n'
    printf '  blank = iconless\n'
    printf '  d     = use default icon if present:\n'
    printf '          %s\n' "$CHILD_DEFAULT_ICON"
    printf '  M     = create a blank icon template at the default location\n'
    printf '  path  = copy that icon into the application directory\n'
    printf 'Icon: '
    IFS= read -r ICON_ENTRY || ICON_ENTRY=""

    CHILD_ICON=""

    case "$ICON_ENTRY" in
        '')
            CHILD_ICON=""
            ;;
        d|D)
            if [ -f "$CHILD_DEFAULT_ICON" ]; then
                CHILD_ICON="$CHILD_DEFAULT_ICON"
            else
                printf 'Default icon does not exist; continuing iconless.\n'
            fi
            ;;
        M|m)
            mkdir -p "$CHILD_SCRIPT_DIR" || true
            if create_blank_icon_template "$CHILD_DEFAULT_ICON"; then
                CHILD_ICON="$CHILD_DEFAULT_ICON"
                printf 'Created blank icon template:\n  %s\n' "$CHILD_ICON"
            else
                printf 'Could not create blank icon template; continuing iconless.\n'
            fi
            ;;
        *)
            CUSTOM_ICON_SOURCE="$(normalize_launch_target "$ICON_ENTRY")"
            if [ ! -f "$CUSTOM_ICON_SOURCE" ]; then
                printf 'Custom icon not found; continuing iconless:\n  %s\n' "$CUSTOM_ICON_SOURCE"
            else
                ICON_EXT="${CUSTOM_ICON_SOURCE##*.}"
                [ "$ICON_EXT" != "$CUSTOM_ICON_SOURCE" ] || ICON_EXT="png"
                CHILD_ICON="$CHILD_SCRIPT_DIR/icon.$ICON_EXT"
                cp -f "$CUSTOM_ICON_SOURCE" "$CHILD_ICON" ||
                    die "Could not copy custom icon into application directory."
                printf 'Copied icon:\n  %s\n' "$CHILD_ICON"
            fi
            ;;
    esac

    printf '\nCategory [Other] (blank or d = Other): '
    IFS= read -r CHILD_CATEGORY || CHILD_CATEGORY=""
    case "$CHILD_CATEGORY" in
        ''|d|D) CHILD_CATEGORY="Other" ;;
    esac
    CHILD_CATEGORY="$(printf '%s' "$CHILD_CATEGORY" | sed 's/[^A-Za-z0-9]//g')"
    [ -n "$CHILD_CATEGORY" ] || CHILD_CATEGORY="Other"

    ID_SAFE_NAME="$(printf '%s' "$CHILD_CUSTOM_NAME" | sed 's/[^A-Za-z0-9._ -]/-/g; s/[[:space:]]\+/-/g')"
    [ -n "$ID_SAFE_NAME" ] || ID_SAFE_NAME="Managed-App"
    CHILD_IDENTITY="${ID_SAFE_NAME}-${CHILD_CATEGORY}.sh"

    printf '\nInstall summary:\n'
    printf '  Identity  : %s\n' "$CHILD_IDENTITY"
    printf '  App name  : %s\n' "$CHILD_CUSTOM_NAME"
    printf '  Start.sh  : %s\n' "$CHILD_LOCAL_START"
    printf '  Payload   : %s\n' "$CHILD_PAYLOAD_TARGET"
    printf '  Source    : %s\n' "$CHILD_SOURCE_SCRIPT"
    printf '  Run dir   : %s\n' "$CHILD_SCRIPT_DIR"
    [ -n "$CHILD_LAUNCH_COMMAND" ] &&
        printf '  Command   : %s\n' "$CHILD_LAUNCH_COMMAND" ||
        printf '  Command   : direct execution\n'
    [ -n "$CHILD_ICON" ] &&
        printf '  Icon      : %s\n' "$CHILD_ICON" ||
        printf '  Icon      : none\n'
    printf '  Category  : %s\n\n' "$CHILD_CATEGORY"

    RZ27_INSTALLER_IDENTITY="$CHILD_IDENTITY" \
    RZ27_INSTALL_DIR="$INSTALL_DIR" \
    RZ27_MANAGER_CHILD=1 \
    RZ27_SELECTED_LAUNCH_TARGET="$CHILD_LOCAL_START" \
    RZ27_CUSTOM_LAUNCH_COMMAND="" \
    RZ27_CUSTOM_APP_NAME="$CHILD_CUSTOM_NAME" \
    RZ27_CUSTOM_ICON_FILE="$CHILD_ICON" \
    RZ27_CUSTOM_WORKDIR="$CHILD_SCRIPT_DIR" \
    RZ27_SOURCE_SCRIPT="$CHILD_PAYLOAD_TARGET" \
        "$INSTALLER_FILE"

    CHILD_INSTALL_STATUS=$?

    if [ "$CHILD_INSTALL_STATUS" -ne 0 ]; then
        printf '\nInstallation did not complete successfully.\n'
        return "$CHILD_INSTALL_STATUS"
    fi

    LAST_CHILD_IDENTITY="$CHILD_IDENTITY"
    LAST_CHILD_APP_NAME="$CHILD_CUSTOM_NAME"
    LAST_CHILD_ICON="$CHILD_ICON"
    LAST_CHILD_SOURCE="$CHILD_SOURCE_SCRIPT"

    offer_editor_after_install "$CHILD_PAYLOAD_TARGET" "$CHILD_SCRIPT_DIR"
}

manager_remove_child()
{
    COUNT="$(managed_install_count)"
    if [ "$COUNT" -eq 0 ]; then
        printf '\nNo managed applications are currently installed.\n'
        printf 'Uninstall the Installer application itself? [y/N]: '
        IFS= read -r REMOVE_INSTALLER || REMOVE_INSTALLER=""

        case "$REMOVE_INSTALLER" in
            y|Y|yes|YES|Yes)
                remove_installer_manager
                rz27_registry_cleanup_if_empty
                printf '\nInstaller application removed.\n'
                ;;
            *)
                printf '\nInstaller preserved.\n'
                ;;
        esac
        return 0
    fi

    printf '\nManaged applications:\n'
    list_managed_installs
    printf '\nSelect application number to uninstall: '
    IFS= read -r SELECTION || return 0

    case "$SELECTION" in
        ''|*[!0-9]*)
            printf 'Invalid selection.\n'
            return 0
            ;;
    esac

    CHILD_IDENTITY="$(managed_install_name_by_index "$SELECTION")" || {
        printf 'Invalid selection.\n'
        return 0
    }

    RZ27_INSTALLER_IDENTITY="$CHILD_IDENTITY" \
    RZ27_INSTALL_DIR="$INSTALL_DIR" \
    RZ27_MANAGER_CHILD=1 \
        "$INSTALLER_FILE" -u
}

installer_manager_menu()
{
    while :; do
        COUNT="$(managed_install_count)"

        printf '\n'
        printf '============================================================\n'
        printf ' Installer Manager\n'
        printf '============================================================\n'
        printf 'Managed applications: %s\n' "$COUNT"
        printf '\n'
        printf '0) Install the Installer itself\n'
        printf '1) Install another application\n'
        printf '2) Remove an installed application\n'
        printf '3) List installed applications\n'
        printf '4) Show transparent install registry\n'
        printf '5) Exit\n'
        printf '\n'
        printf 'Selection: '

        IFS= read -r CHOICE || exit 0

        case "$CHOICE" in
            0)
                printf '\nInstalling/repairing the dedicated Installer application...\n'
                printf 'Refreshing launcher, icon, and Installer support files.\n'
                printf 'The install registry will be preserved.\n'
                repair_installer_manager
                printf 'Installer application is repaired/updated and registered with its default icon.\n'
                ;;
            1) manager_install_child ;;
            2) manager_remove_child ;;
            3)
                printf '\n'
                if [ "$COUNT" -eq 0 ]; then
                    printf 'No managed applications installed.\n'
                else
                    list_managed_installs
                fi
                ;;
            4)
                rz27_registry_show
                ;;
            5|'') exit 0 ;;
            *) printf 'Invalid selection.\n' ;;
        esac
    done
}

# ============================================================
# UNINSTALL
# ============================================================

uninstall_linux()
{
    linux_desktop_file

    if [ -f "$LINUX_DESKTOP_FILE" ] && command -v xdg-desktop-menu >/dev/null 2>&1; then
        run_linux_elevated xdg-desktop-menu uninstall --mode system "$LINUX_DESKTOP_FILE"             >/dev/null 2>&1 || true
    fi

    run_linux_elevated rm -f "$LINUX_DESKTOP_FILE" ||
        die "Could not remove Linux system launcher: $LINUX_DESKTOP_FILE"

    run_linux_elevated rm -f "$LINUX_SYSTEM_ICON" >/dev/null 2>&1 || true
    run_linux_elevated rm -f "$LINUX_SYSTEM_WRAPPER" >/dev/null 2>&1 || true

    if linux_is_pantheon; then
        pantheon_remove_launcher_from_dock
        refresh_pantheon_dock
    fi

    # Also remove launchers written by older per-user revisions.
    rm -f "$LINUX_OLD_USER_DESKTOP" "$LINUX_NAMESPACED_USER_DESKTOP" 2>/dev/null || true
    if [ "$LINUX_LEGACY_USER_DESKTOP" != "$LINUX_OLD_USER_DESKTOP" ]; then
        rm -f "$LINUX_LEGACY_USER_DESKTOP" 2>/dev/null || true
    fi

    run_linux_elevated rm -f         "$LINUX_OLD_SYSTEM_DESKTOP"         "$LINUX_OLD_SYSTEM_ICON"         "$LINUX_OLD_SYSTEM_WRAPPER" >/dev/null 2>&1 || true

    if command -v update-desktop-database >/dev/null 2>&1; then
        run_linux_elevated update-desktop-database "$LINUX_APPLICATIONS_DIR" >/dev/null 2>&1 || true
    fi

    if command -v gtk-update-icon-cache >/dev/null 2>&1; then
        run_linux_elevated gtk-update-icon-cache -f -t /usr/share/icons/hicolor >/dev/null 2>&1 || true
    fi

    if command -v xdg-desktop-menu >/dev/null 2>&1; then
        xdg-desktop-menu forceupdate >/dev/null 2>&1 || true
    fi

    refresh_pantheon_applications_menu

    printf '\nLinux system-wide application launcher removed.\n'
}

uninstall_macos()
{
    mac_paths

    LSREGISTER="/System/Library/Frameworks/CoreServices.framework/Frameworks/LaunchServices.framework/Support/lsregister"
    if [ -x "$LSREGISTER" ] && [ -d "$MAC_APP_DIR" ]; then
        "$LSREGISTER" -u "$MAC_APP_DIR" >/dev/null 2>&1 || true
    fi

    if [ -d "$MAC_APP_DIR" ]; then
        run_mac_elevated rm -rf "$MAC_APP_DIR" ||
            die "Could not remove macOS application: $MAC_APP_DIR"
    fi

    printf '\nmacOS system application removed.\\n'
}

uninstall_windows()
{
    windows_paths

    SHORTCUT_PS="$(windows_escape_ps_single "$WIN_SHORTCUT_NATIVE")"

    if windows_shortcut_registered; then
        "$POWERSHELL_EXE" -NoProfile -ExecutionPolicy Bypass -Command \
            "Start-Process PowerShell -Verb RunAs -Wait -ArgumentList '-NoProfile','-Command','Remove-Item -LiteralPath ''$SHORTCUT_PS'' -Force -ErrorAction SilentlyContinue'" \
            >/dev/null 2>&1 || true
    fi

    windows_unregister_add_remove_programs

    printf '\nWindows all-users Start Menu launcher and Add or Remove Programs entry removed.\n'
}

cleanup_generated_support()
{
    # Remove installer-generated runtime/support state. On Windows this also
    # removes the generated icon.ico and windows-run.cmd stored in .launcher.
    if [ -d "$STATE_DIR" ]; then
        rm -rf "$STATE_DIR" ||
            die "Could not remove launcher support directory: $STATE_DIR"
    fi

    # Remove the shared launcher root only when no other installer-name
    # identities remain.
    if [ -d "$LAUNCHER_ROOT" ]; then
        rmdir "$LAUNCHER_ROOT" 2>/dev/null || true
    fi

    # icon.png remains the shared source icon unless this is the final
    # installation identity in the directory.
    if [ ! -d "$LAUNCHER_ROOT" ] && [ -f "$ICON_FILE" ]; then
        rm -f "$ICON_FILE" ||
            die "Could not remove icon.png: $ICON_FILE"
    fi
}

uninstall_current_platform()
{
    case "$PLATFORM" in
        linux)
            uninstall_linux
            ;;
        macos)
            uninstall_macos
            ;;
        windows)
            uninstall_windows
            ;;
        *)
            die "Unsupported platform for uninstall: $PLATFORM"
            ;;
    esac

    cleanup_generated_support
    rz27_registry_remove_current

    REMAINING="$(managed_install_count)"
    if [ "$REMAINING" -eq 0 ]; then
        printf '\nNo managed applications remain. Removing Installer manager...\n'
        remove_installer_manager
        rz27_registry_cleanup_if_empty
    else
        printf '\n%s managed application(s) remain; Installer manager preserved.\n' "$REMAINING"
    fi

    printf '\n'
    printf 'Uninstall complete.\n'
    printf 'Removed:\n'
    printf '  platform launcher\n'
    printf '  generated platform icon/support files\n'
    printf '  launcher state\n'
    printf '  this install\047s Start.sh\n'
    printf '  icon.png when no other named installs remain\n'
    printf '\n'
    printf 'Preserved installer/application directory:\n'
    printf '  %s\n' "$INSTALL_DIR"
    printf '\n'
}


uninstall_only_mode()
{
    printf '\n'
    printf '============================================================\n'
    printf ' RZ-27 Uninstall Only Mode\n'
    printf '============================================================\n'
    printf '\n'
    printf 'This mode does not install, update, bootstrap, or launch apps.\n'
    printf '\n'

    while :; do
        COUNT="$(managed_install_count)"

        if [ "$COUNT" -eq 0 ]; then
            printf 'No managed applications remain.\n'
            printf 'Uninstall the Installer application and its remaining files? [y/N]: '
            IFS= read -r REMOVE_MANAGER || REMOVE_MANAGER=""

            case "$REMOVE_MANAGER" in
                y|Y|yes|YES|Yes)
                    remove_installer_manager
                    rz27_registry_cleanup_if_empty
                    rm -f "$ICON_FILE" 2>/dev/null || true
                    rmdir "$LAUNCHER_ROOT" 2>/dev/null || true
                    printf '\nInstaller application and remaining managed support files removed.\n'
                    ;;
                *)
                    printf '\nInstaller preserved.\n'
                    ;;
            esac
            return 0
        fi

        printf 'Managed applications available to uninstall: %s\n\n' "$COUNT"
        list_managed_installs
        printf '\n'
        printf 'Enter an application number to uninstall.\n'
        printf 'q = exit uninstall mode\n'
        printf '> '

        IFS= read -r UNINSTALL_SELECTION || return 0

        case "$UNINSTALL_SELECTION" in
            q|Q|'')
                return 0
                ;;
            *[!0-9]*)
                printf 'Invalid selection.\n\n'
                continue
                ;;
        esac

        CHILD_IDENTITY="$(managed_install_name_by_index "$UNINSTALL_SELECTION")" || {
            printf 'Invalid selection.\n\n'
            continue
        }

        RZ27_INSTALLER_IDENTITY="$CHILD_IDENTITY" \
        RZ27_INSTALL_DIR="$INSTALL_DIR" \
        RZ27_MANAGER_CHILD=1 \
            "$INSTALLER_FILE" -u-child

        printf '\n'
    done
}

# ============================================================
# MAIN
# ============================================================

# Detect the platform before any first-run/bootstrap work.
detect_platform
refresh_app_name

# ------------------------------------------------------------
# Uninstall-only dispatch comes first. Nothing below this branch is allowed
# to bootstrap, register, update, or launch applications.
# ------------------------------------------------------------
if [ "${1:-}" = "-u" ]; then
    uninstall_only_mode
    exit 0
fi

# Internal child-removal entry used only by uninstall_only_mode.
if [ "${1:-}" = "-u-child" ]; then
    uninstall_current_platform
    exit 0
fi

# ------------------------------------------------------------
# Normal mode
# ------------------------------------------------------------
# First normal run establishes the persistent Installer manager.
if ! manager_is_installed; then
    mkdir -p "$STATE_DIR" 2>/dev/null || true
    bootstrap_default_icon_once
    check_icon
    ensure_installer_manager

    printf '\nFirst run complete.\n'
    printf 'A dedicated "%s" application has been installed.\n' "$MANAGER_NAME"
    rz27_registry_paths
    printf 'Transparent install registry:\n  %s\n\n' "$RZ27_INSTALL_LOG"
fi

# Running normally always presents the five-option manager menu.
if [ "${1:-}" = "--manager" ] || [ -z "${RZ27_MANAGER_CHILD:-}" ]; then
    ensure_installer_manager
    installer_manager_menu
    exit 0
fi

# Child-install execution path, entered by the manager only.
ensure_installer_manager
configure_start_for_install
bootstrap_default_icon_once
check_icon
prepare_scripts

case "$PLATFORM" in
    linux)
        if linux_launcher_is_current; then
            run_linux_start
            exit $?
        fi
        printf '\nLinux launcher is missing or outdated; installing/updating it...\n'
        install_linux_launcher || exit 1
        ;;
    macos)
        if mac_launcher_is_current; then
            run_macos_start
            exit $?
        fi
        printf '\nmacOS launcher is missing or outdated; installing/updating it...\n'
        install_mac_launcher
        ;;
    windows)
        if windows_shortcut_matches; then
            run_windows_start
            exit $?
        fi
        printf '\nWindows launcher is missing or outdated; installing/updating it...\n'
        install_windows_launcher
        ;;
esac

printf 'Application : %s\n' "$APP_NAME"
printf 'Install dir : %s\n' "$INSTALL_DIR"
printf 'Start script: %s\n' "$START_FILE"
printf '\nLauncher configuration is current.\n\n'
exit 0

